window.ASK_CD_INDEX = [{"id": "cs-sony-a7iv-first-setup", "type": "lesson", "title": "Sony a7 IV: First Setup", "questions": ["How do I set up my Sony a7 IV for the first time?", "How do I format a memory card on the a7 IV?", "Should I shoot RAW or JPEG on the a7 IV?", "Which RAW file type should I pick on the a7 IV?"], "shortAnswer": "In this order: format the card in the camera (MENU, Shooting, Media, Format), set stills to RAW Lossless Compressed (L), turn SteadyShot on, then save the setup to Camera Set. Memory 1 and put your most-used items in My Menu.", "url": "/camera-select/sony/a7-iv/first-setup.html", "access": "free", "topics": ["setup", "raw", "formatting", "steadyshot", "memory recall"], "level": "beginner", "brand": "Sony", "model": "a7 IV", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7M4 Help Guide (helpguide.sony.net/ilc/2110)", "img": "/media/camera-select/sony-a7iv.jpg"}, {"id": "cs-sony-a7iv-autofocus", "type": "lesson", "title": "Sony a7 IV: Autofocus That Holds Your Subject", "questions": ["Why does my a7 IV keep focusing on the wrong person?", "What focus area should I use on the a7 IV?", "How do I set Eye AF on the a7 IV?", "How do I keep focus on one subject through a crowd on the a7 IV?"], "shortAnswer": "Use AF-C with Tracking: Zone, set Face/Eye Subject to who you are shooting (Human, Animal, or Bird), and set AF Tracking Sensitivity to 1 (Locked on) when one subject has to hold through a crowd; 3 is the balanced default.", "url": "/camera-select/sony/a7-iv/autofocus.html", "access": "free", "topics": ["autofocus", "eye af", "tracking", "focus area"], "level": "beginner", "brand": "Sony", "model": "a7 IV", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7M4 Help Guide (helpguide.sony.net/ilc/2110)", "img": "/media/camera-select/sony-a7iv.jpg"}, {"id": "cs-sony-a7iv-custom-buttons", "type": "lesson", "title": "Sony a7 IV: Custom Buttons", "questions": ["What should I assign to C3 and C4 on the a7 IV?", "How do I customize buttons on the a7 IV?", "How do I put Zebra on a button on the a7 IV?"], "shortAnswer": "A proven map: C3 for Focus Area, C4 for Face/Eye Subject, AEL for Zebra Display. Set them under Setup, Operation Customize, Custom Key/Dial Set., then save the whole map into Camera Set. Memory.", "url": "/camera-select/sony/a7-iv/custom-buttons.html", "access": "pro", "topics": ["custom buttons", "zebra", "workflow"], "level": "intermediate", "brand": "Sony", "model": "a7 IV", "leadsTo": "Camera Select Pro lessons for this model", "status": "verified", "source": "Sony official ILCE-7M4 Help Guide (helpguide.sony.net/ilc/2110)", "img": "/media/camera-select/sony-a7iv.jpg"}, {"id": "cs-sony-a7iv-video-settings", "type": "lesson", "title": "Sony a7 IV: Video Settings", "questions": ["What is the best video format on the a7 IV: XAVC HS, S, or S-I?", "How do I shoot S-Log3 on the a7 IV?", "Why does my a7 IV stop recording video from heat?", "What is S-Cinetone on the a7 IV?"], "shortAnswer": "Default to XAVC S 4K (HS files are smaller but harder to edit, S-I is easiest to edit). Log lives in Picture Profile: PP11 is S-Cinetone for a finished look in camera, PP8 is S-Log3 with S-Gamut3.Cine for grading. There is no Cine EI or Log Shooting menu on this camera.", "url": "/camera-select/sony/a7-iv/video-settings.html", "access": "pro", "topics": ["video", "xavc", "s-log3", "s-cinetone", "zebra", "overheating"], "level": "intermediate", "brand": "Sony", "model": "a7 IV", "leadsTo": "Camera Select Pro lessons for this model", "status": "verified", "source": "Sony official ILCE-7M4 Help Guide (helpguide.sony.net/ilc/2110)", "img": "/media/camera-select/sony-a7iv.jpg"}, {"id": "cs-sony-a7iv-common-fixes", "type": "lesson", "title": "Sony a7 IV: Common Fixes", "questions": ["What are the bright spots in my a7 IV photos?", "How do I clean the a7 IV sensor?", "Why does my a7 IV overheat?", "Why is my a7 IV livestream only 720p?"], "shortAnswer": "Bright spots: run Pixel Mapping (Setup, Setup Option). Dust: Sensor Cleaning, then a blower with the camera face down. Heat: set Auto Power OFF Temp. to High (Setup, Power Setting Option) and follow Sony's warnings. A 720p stream usually means a USB 2.0 connection.", "url": "/camera-select/sony/a7-iv/common-fixes.html", "access": "free", "topics": ["pixel mapping", "sensor cleaning", "overheating", "streaming", "troubleshooting"], "level": "beginner", "brand": "Sony", "model": "a7 IV", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7M4 Help Guide (helpguide.sony.net/ilc/2110)", "img": "/media/camera-select/sony-a7iv.jpg"}, {"id": "cs-sony-a6700-first-setup", "type": "lesson", "title": "Sony a6700: First Setup", "questions": ["How do I set up my Sony a6700 for the first time?", "How do I format a memory card on the a6700?", "Should I shoot RAW or JPEG on the a6700?", "Which RAW file type should I pick on the a6700?"], "shortAnswer": "In this order: format the card in the camera (MENU, Shooting, Media, Format — the a6700 has one SD slot), set stills to RAW Lossless Comp (this body has no L/M/S size options), turn SteadyShot on, then save the setup to Camera Set. Memory 1 and put Format in My Menu.", "url": "/camera-select/sony/a6700/first-setup.html", "access": "free", "topics": ["setup", "raw", "formatting", "steadyshot", "memory recall"], "level": "beginner", "brand": "Sony", "model": "a6700", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-6700 Help Guide (helpguide.sony.net/ilc/2320)", "img": "/media/camera-select/sony-a6700.jpg"}, {"id": "cs-sony-a6700-autofocus", "type": "lesson", "title": "Sony a6700: Autofocus That Holds Your Subject", "questions": ["Why does my a6700 keep focusing on the wrong subject?", "What focus area should I use on the a6700?", "How do I set up subject recognition on the a6700?", "What is the best autofocus setup for birds on the a6700?"], "shortAnswer": "Use AF-C with a Tracking focus area, and name the subject exactly under MENU, Focus, Subject Recognition, Recognition Target — Human, Animal/Bird, Animal, Bird, Insect, Car/Train, or Airplane; the AI processing unit tunes itself to the named subject. For portraits, set Right/Left Eye Select to the near eye.", "url": "/camera-select/sony/a6700/autofocus.html", "access": "free", "topics": ["autofocus", "eye af", "tracking", "subject recognition"], "level": "beginner", "brand": "Sony", "model": "a6700", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-6700 Help Guide (helpguide.sony.net/ilc/2320)", "img": "/media/camera-select/sony-a6700.jpg"}, {"id": "cs-sony-a6700-custom-buttons", "type": "lesson", "title": "Sony a6700: Custom Buttons", "questions": ["How do I assign custom buttons on the a6700?", "What should I put on my a6700 custom keys?", "How do I change the recognition target fast on the a6700?", "How do I save my a6700 button settings?"], "shortAnswer": "Assign in MENU, Setup, Operation Customize, Custom Key/Dial Set. — the stills and movie maps are separate. Put Focus Area on one key and Recognition Target on another, Auto Framing on the movie map, then save the whole map to Camera Set. Memory 1.", "url": "/camera-select/sony/a6700/custom-buttons.html", "access": "pro", "topics": ["custom buttons", "focus area", "subject recognition", "auto framing"], "level": "beginner", "brand": "Sony", "model": "a6700", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-6700 Help Guide (helpguide.sony.net/ilc/2320)", "img": "/media/camera-select/sony-a6700.jpg"}, {"id": "cs-sony-a6700-video-settings", "type": "lesson", "title": "Sony a6700: Video Settings", "questions": ["What is the best video format on the a6700?", "How do I shoot S-Log3 on the a6700?", "Does the a6700 have Cine EI?", "Why does 4K 120p look more zoomed in on the a6700?"], "shortAnswer": "Default to XAVC S 4K 10-bit. For footage that ships ungraded use PP11 (S-Cinetone); for graded footage switch Log Shooting On (Flexible ISO) — this body has no S-Log3 profile preset and no Cine EI mode. 4K 120p is a regular frame rate, but the angle of view tightens to about 1.6x.", "url": "/camera-select/sony/a6700/video-settings.html", "access": "pro", "topics": ["video", "xavc", "s-log3", "s-cinetone", "4k 120p"], "level": "beginner", "brand": "Sony", "model": "a6700", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-6700 Help Guide (helpguide.sony.net/ilc/2320)", "img": "/media/camera-select/sony-a6700.jpg"}, {"id": "cs-sony-a6700-common-fixes", "type": "lesson", "title": "Sony a6700: Common Fixes", "questions": ["Why does my a6700 shut down from heat when recording?", "Why is my framing tighter at 4K 120p on the a6700?", "How do I fix focus breathing on the a6700?", "Why does my a6700 focus on the wrong subject?"], "shortAnswer": "Heat shutdowns: set Auto Power OFF Temp. to High (MENU, Setup, Power Setting Option). The tighter frame at 4K 120p is the 1.6x sensor readout, not a fault. Focus breathing: set Breathing Comp. to On inside Lens Compensation. Wrong subject: check the Recognition Target — it is usually still set to the last subject you shot.", "url": "/camera-select/sony/a6700/common-fixes.html", "access": "free", "topics": ["overheating", "troubleshooting", "focus breathing", "subject recognition"], "level": "beginner", "brand": "Sony", "model": "a6700", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-6700 Help Guide (helpguide.sony.net/ilc/2320)", "img": "/media/camera-select/sony-a6700.jpg"}, {"id": "cs-sony-a7cii-first-setup", "type": "lesson", "title": "Sony a7C II: First Setup", "questions": ["How do I set up my Sony a7C II for the first time?", "How do I format a memory card on the a7C II?", "Should I shoot RAW or JPEG on the a7C II?", "Which RAW file type should I pick on the a7C II?"], "shortAnswer": "In this order: format the card in the camera (MENU, Shooting, Media, Format — the a7C II has one SD slot), set stills to RAW Lossless Comp (L), turn SteadyShot on, then save the setup to Camera Set. Memory 1 and put Format in My Menu.", "url": "/camera-select/sony/a7c-ii/first-setup.html", "access": "free", "topics": ["setup", "raw", "formatting", "steadyshot", "memory recall"], "level": "beginner", "brand": "Sony", "model": "a7C II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7CM2 Help Guide (helpguide.sony.net/ilc/2360)", "img": "/media/camera-select/sony-a7cii.jpg"}, {"id": "cs-sony-a7cii-autofocus", "type": "lesson", "title": "Sony a7C II: Autofocus That Holds Your Subject", "questions": ["Why does my a7C II keep focusing on the wrong subject?", "What focus area should I use on the a7C II?", "How do I set up subject recognition on the a7C II?", "What is the best autofocus setup for birds on the a7C II?"], "shortAnswer": "Use AF-C with a Tracking focus area, and name the subject exactly under MENU, Focus, Subject Recognition, Recognition Target — Auto, Human, Animal/Bird, Animal, Bird, Insect, Car/Train, or Airplane; the AI processing unit tunes itself to the named subject. For portraits, set Right/Left Eye Select to the near eye.", "url": "/camera-select/sony/a7c-ii/autofocus.html", "access": "free", "topics": ["autofocus", "eye af", "tracking", "subject recognition"], "level": "beginner", "brand": "Sony", "model": "a7C II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7CM2 Help Guide (helpguide.sony.net/ilc/2360)", "img": "/media/camera-select/sony-a7cii.jpg"}, {"id": "cs-sony-a7cii-custom-buttons", "type": "lesson", "title": "Sony a7C II: Custom Buttons", "questions": ["How do I assign custom buttons on the a7C II?", "What should I put on my a7C II custom buttons?", "How do I change the recognition target fast on the a7C II?", "How do I save my a7C II button settings?"], "shortAnswer": "Assign in MENU, Setup, Operation Customize, Custom Key/Dial Set. — the stills and movie maps are separate. Put Focus Area on Custom Button 1 and Recognition Target on Custom Button 2, Auto Framing on the movie map, then save the whole map to Camera Set. Memory 1.", "url": "/camera-select/sony/a7c-ii/custom-buttons.html", "access": "pro", "topics": ["custom buttons", "focus area", "subject recognition", "auto framing"], "level": "beginner", "brand": "Sony", "model": "a7C II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7CM2 Help Guide (helpguide.sony.net/ilc/2360)", "img": "/media/camera-select/sony-a7cii.jpg"}, {"id": "cs-sony-a7cii-video-settings", "type": "lesson", "title": "Sony a7C II: Video Settings", "questions": ["What is the best video format on the a7C II?", "How do I shoot S-Log3 on the a7C II?", "Does the a7C II have Cine EI?", "Why does 4K 60p look more zoomed in on the a7C II?"], "shortAnswer": "Default to XAVC S 4K 10-bit. For footage that ships ungraded use PP11 (S-Cinetone); for graded footage switch Log Shooting On (Flexible ISO) — there is no Cine EI mode on this body. 4K tops out at 60p, and at 60p the Super 35 crop is locked on, tightening the angle of view to about 1.5x.", "url": "/camera-select/sony/a7c-ii/video-settings.html", "access": "pro", "topics": ["video", "xavc", "s-log3", "s-cinetone", "4k 60p"], "level": "beginner", "brand": "Sony", "model": "a7C II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7CM2 Help Guide (helpguide.sony.net/ilc/2360)", "img": "/media/camera-select/sony-a7cii.jpg"}, {"id": "cs-sony-a7cii-common-fixes", "type": "lesson", "title": "Sony a7C II: Common Fixes", "questions": ["Why does my a7C II shut down from heat when recording?", "Why is my framing tighter at 4K 60p on the a7C II?", "How do I fix focus breathing on the a7C II?", "How do I move the focus point on the a7C II without a joystick?"], "shortAnswer": "Heat shutdowns: set Auto Power OFF Temp. to High (MENU, Setup, Power Setting Option) — about 60 minutes of 4K at 25°C. The tighter frame at 4K 60p is the locked Super 35 crop, not a fault. Focus breathing: set Breathing Comp. to On inside Lens Compensation. Moving the focus point: this body has no joystick — use the control wheel buttons or Touch Focus.", "url": "/camera-select/sony/a7c-ii/common-fixes.html", "access": "free", "topics": ["overheating", "troubleshooting", "focus breathing", "touch focus"], "level": "beginner", "brand": "Sony", "model": "a7C II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Sony official ILCE-7CM2 Help Guide (helpguide.sony.net/ilc/2360)", "img": "/media/camera-select/sony-a7cii.jpg"}, {"id": "cs-canon-r6ii-first-setup", "type": "lesson", "title": "Canon EOS R6 II: First Setup", "questions": ["How do I set up my Canon EOS R6 II for the first time?", "How do I format a memory card on the R6 II?", "Should I shoot RAW or C-RAW on the R6 II?", "How do I back up photos to both cards on the R6 II?"], "shortAnswer": "In this order: format both cards (Set-up -> Format card), set Rec. to multiple so every still lands on both cards, shoot RAW (C-RAW is the same capture at about half the file size), set Still photo IS to Always, then register the whole setup to C1.", "url": "/camera-select/canon/eos-r6-ii/first-setup.html", "access": "free", "topics": ["setup", "raw", "formatting", "dual cards", "c1"], "level": "beginner", "brand": "Canon", "model": "EOS R6 II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Canon official EOS R6 Mark II Advanced User Guide (cam.start.canon/en/C012)", "img": "/media/camera-select/canon-r6ii.jpg"}, {"id": "cs-canon-r6ii-autofocus", "type": "lesson", "title": "Canon EOS R6 II: Autofocus", "questions": ["How do I set up autofocus on the R6 II?", "Why won't my R6 II track a moving subject?", "How does subject detection work on the R6 II?", "Which AF case should I use on the R6 II?"], "shortAnswer": "Servo AF, Flexible Zone AF for control or Whole area AF with tracking for movers, Subject to detect named exactly (People, Animals, Vehicles), and Case A to tune how tracking behaves. For portraits, set Eye detection to the near eye.", "url": "/camera-select/canon/eos-r6-ii/autofocus.html", "access": "free", "topics": ["autofocus", "tracking", "servo af", "subject detection", "eye detection"], "level": "beginner", "brand": "Canon", "model": "EOS R6 II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Canon official EOS R6 Mark II Advanced User Guide (cam.start.canon/en/C012)", "img": "/media/camera-select/canon-r6ii.jpg"}, {"id": "cs-canon-r6ii-custom-buttons", "type": "lesson", "title": "Canon EOS R6 II: Custom Buttons", "questions": ["How do I customize buttons on the R6 II?", "Where is Customize buttons on the R6 II?", "What should the M-Fn button do on the R6 II?"], "shortAnswer": "Assign under Custom Functions -> Customize buttons: M-Fn takes Direct AF area selection, the AE lock button takes Direct select of subject to detect, and depth-of-field preview becomes Eye Detection AF. The control ring is assigned under Customize dials.", "url": "/camera-select/canon/eos-r6-ii/custom-buttons.html", "access": "pro", "topics": ["custom buttons", "m-fn", "customize dials", "button map"], "level": "beginner", "brand": "Canon", "model": "EOS R6 II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Canon official EOS R6 Mark II Advanced User Guide (cam.start.canon/en/C012)", "img": "/media/camera-select/canon-r6ii.jpg"}, {"id": "cs-canon-r6ii-video-settings", "type": "lesson", "title": "Canon EOS R6 II: Video Settings", "questions": ["What are the best video settings on the R6 II?", "How do I turn on Canon Log on the R6 II?", "How do I shoot slow motion on the R6 II?", "How long can the R6 II record 4K video?"], "shortAnswer": "4K 59.94 in IPB (Standard), Canon Log 3 via Canon Log settings -> On (C.LOG3) at ISO 800 or higher for graded work, and 179.82 fps High Frame Rate for 1/6-speed slow motion. Plan batteries: about 1 hr 20 min of 4K 59.94 per LP-E6NH, and this body has no high-temperature setting.", "url": "/camera-select/canon/eos-r6-ii/video-settings.html", "access": "pro", "topics": ["video", "canon log 3", "slow motion", "4k", "recording time"], "level": "beginner", "brand": "Canon", "model": "EOS R6 II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Canon official EOS R6 Mark II Advanced User Guide (cam.start.canon/en/C012)", "img": "/media/camera-select/canon-r6ii.jpg"}, {"id": "cs-canon-r6ii-common-fixes", "type": "lesson", "title": "Canon EOS R6 II: Common Fixes", "questions": ["Why did my R6 II only record to one card?", "How do I fix focus breathing on the R6 II?", "Why does my R6 II focus on the wrong subject?", "Why won't my R6 II shutter fire with a manual lens?"], "shortAnswer": "One card filled: Rec. to multiple was never set. Pulsing focus on video: Focus breathing correction (needs Distortion correction enabled). Wrong subject: Subject to detect. Manual lens: set its focal length under IS mode, and enable Release shutter w/o lens.", "url": "/camera-select/canon/eos-r6-ii/common-fixes.html", "access": "free", "topics": ["troubleshooting", "dual cards", "focus breathing", "manual lens"], "level": "beginner", "brand": "Canon", "model": "EOS R6 II", "leadsTo": "Field Manual No. 01 (full camera-craft course)", "status": "verified", "source": "Canon official EOS R6 Mark II Advanced User Guide (cam.start.canon/en/C012)", "img": "/media/camera-select/canon-r6ii.jpg"}, {"id": "protocol-001", "type": "protocol", "title": "Protocol 001: The 3-Second Reset", "questions": ["I freeze up during important moments on a shoot, what do I do?", "How do I calm down fast when the pressure hits while shooting?", "My hands shake when a big moment is coming, how do I recover?"], "shortAnswer": "Pressure on a shoot is a body problem, not a skill problem: adrenaline and shallow breathing lock you up even when you know what to do. This protocol gives you a 3-second reset, a short circuit breaker that tells your body the danger has passed so you can reach your skills again.", "url": "/protocol-001.html", "access": "free", "topics": ["confidence", "pressure", "mindset"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Protocol 012: The Confidence Pause", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-001.png"}, {"id": "protocol-002", "type": "protocol", "title": "Protocol 002: Protect the Shot", "questions": ["How do I stop spraying lots of photos and hoping one works?", "What should I decide before I press the shutter?", "How do I make sure I get the one shot that matters at a session?"], "shortAnswer": "Before you lift the camera, name the hero of the frame: what this photo is trying to say. When that one decision comes first, your focus, exposure, and timing all serve it, and a few seconds of intention protect the shot better than thirty frames of hope.", "url": "/protocol-002.html", "access": "free", "topics": ["composition", "intention", "sessions"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Protocol 012: The Confidence Pause", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-002.png"}, {"id": "protocol-003", "type": "protocol", "title": "Protocol 003: The Invisible Director", "questions": ["What do I say to pose people without it getting awkward?", "How do I direct subjects who freeze in front of the camera?", "Posing instructions make my subjects look stiff, what works instead?"], "shortAnswer": "Stop giving body-part instructions like chin down and shoulders back; people freeze because nobody knows what their own chin is doing. Give them one action word instead, like walk, lean, or laugh, because the body already knows how to do actions, and the pose follows on its own.", "url": "/protocol-003.html", "access": "free", "topics": ["posing", "directing", "portraits"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01: Camera Craft", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-003.png"}, {"id": "protocol-004", "type": "protocol", "title": "Protocol 004: I Belong Here", "questions": ["I feel like a fraud at paid shoots, how do I get through it?", "What do I do when I feel out of place at a fancy venue?", "How do I stop comparing myself to other photographers on a job?"], "shortAnswer": "Feeling like a fraud is a comparison glitch: you are comparing your nerves and fumbling behind the scenes to everyone else's finished results. Do not fake confidence; start shooting, because the fraud feeling only survives about 10 minutes once you are actually working, and action builds the confidence instead of waiting for it.", "url": "/protocol-004.html", "access": "free", "topics": ["confidence", "imposter syndrome", "mindset"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Protocol 001: The 3-Second Reset", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-004.png"}, {"id": "protocol-005", "type": "protocol", "title": "Protocol 005: The One Setting That Saves Indoor Birthday Parties", "questions": ["Why are my indoor birthday party photos blurry and orange?", "What settings stop motion blur in a dark room without a flash?", "My indoor photos come out smeary even with a good camera, what's wrong?"], "shortAnswer": "In a dark room the camera exposes for the room, not the faces, and drags the shutter slow enough to blur everything that moves. Tell it your priority: Auto ISO with a minimum shutter speed, and let the ISO rise as high as it needs. 1/125 of a second freezes slow adult movement; playing kids and gesturing hands usually need 1/250 to 1/500.", "url": "/protocol-005.html", "access": "free", "topics": ["indoor", "low light", "shutter speed", "iso"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01: Camera Craft", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/media/protocol-cards/protocol-005.png"}, {"id": "protocol-006", "type": "protocol", "title": "Protocol 006: Why Your Camera Keeps Focusing on the Wrong Thing", "questions": ["Why does my camera focus on the background instead of my subject?", "How do I stop autofocus picking the wrong thing in the frame?", "My camera keeps focusing on flowers and edges instead of faces, how do I fix it?"], "shortAnswer": "Autofocus does not see subjects; it grabs the closest, highest-contrast edge inside whatever area you let it search, so the whole frame gives it a hundred chances to pick wrong. The fix is one focus point, placed by you on the thing that matters, so the camera has no choice but yours.", "url": "/protocol-006.html", "access": "free", "topics": ["autofocus", "focus point", "sharpness"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Camera Select autofocus lessons", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-006.png"}, {"id": "protocol-007", "type": "protocol", "title": "Protocol 007: The Metering Mistake", "questions": ["Why do my snow photos come out gray instead of white?", "When should I override my camera's meter?", "My meter says zero but the photo still looks wrong, why?"], "shortAnswer": "The meter is not measuring what is right; it is forcing every scene toward middle gray, so snow and white dresses get darkened until white looks gray. Override it with exposure compensation: for a snow or white-dress scene, about +1.3 makes white look white again.", "url": "/protocol-007.html", "access": "free", "topics": ["exposure", "metering", "exposure compensation"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01: Camera Craft", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/media/protocol-cards/protocol-007.png"}, {"id": "protocol-008", "type": "protocol", "title": "Protocol 008: The 3-Quote Rule", "questions": ["How do I quote a client without them haggling the price down?", "Should I give clients one price or options?", "Clients always negotiate my single quote, what should I do instead?"], "shortAnswer": "One price is a yes-or-no question, and no is the easiest answer, so a single quote turns into haggling against yourself. Present three options instead: the question becomes which version they want, most people land in the middle, so build the middle option as the one you actually want to sell.", "url": "/protocol-008.html", "access": "free", "topics": ["pricing", "quotes", "clients", "business"], "level": "pro", "brand": "", "model": "", "leadsTo": "Protocol 013: How to Price Your First 10 Clients", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-008.png"}, {"id": "protocol-009", "type": "protocol", "title": "Protocol 009: Manual Mode Isn't a Test — It's a Tool", "questions": ["Do I have to shoot in manual mode to be a real photographer?", "When is manual mode actually the right choice?", "My manual mode photos keep swinging too bright or too dark outdoors, why?"], "shortAnswer": "Manual mode is a tool, not a rank: it does one thing well, locking the exposure when the light is not changing, like studio work or open shade. Set aperture, shutter, and ISO once and leave them; when the light keeps shifting, let the camera carry one of the three instead of spending the shoot reading the meter.", "url": "/protocol-009.html", "access": "free", "topics": ["manual mode", "exposure", "settings"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01: Camera Craft", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-009.png"}, {"id": "protocol-010", "type": "protocol", "title": "Protocol 010: The One Lens That Makes You a Better Photographer", "questions": ["Which one lens would actually make me a better photographer?", "Is a zoom lens making my photos all look the same?", "Why do photographers recommend a 50mm prime lens?"], "shortAnswer": "A versatile zoom lets you stand in one spot and twist, so every photo becomes the view from wherever you happened to be standing. A 50mm prime removes that shortcut: your feet become the zoom, you move closer or step back on purpose, and within weeks you start seeing in 50mm before the camera leaves the bag.", "url": "/protocol-010.html", "access": "free", "topics": ["lenses", "50mm", "composition"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Protocol 014: What to Buy First (When You Have $500)", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-010.png"}, {"id": "protocol-011", "type": "protocol", "title": "Protocol 011: The White Balance Lie", "questions": ["Why do my indoor photos look yellow?", "How do I fix orange skin tones from indoor lighting?", "Auto white balance makes everyone look yellow at receptions, what setting fixes it?"], "shortAnswer": "Warm indoor bulbs burn at roughly 3200 Kelvin, deep orange, and auto white balance tries to split the difference and lands on yellow faces. Stop letting it guess: set white balance to 3200K yourself under tungsten light, and white looks white because you said so.", "url": "/protocol-011.html", "access": "free", "topics": ["white balance", "color", "indoor"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 02: The Finish (fixing color in editing)", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/media/protocol-cards/protocol-011.png"}, {"id": "protocol-012", "type": "protocol", "title": "Protocol 012: The Confidence Pause", "questions": ["I take hundreds of photos but never really see the scene, how do I slow down?", "How do I stop spray-and-pray shooting?", "What should I do in the moment before pressing the shutter?"], "shortAnswer": "Your first glance only gets the quick outline of a scene; the light, the background, and the gesture about to happen show up when you keep looking. Take a deliberate pause before shooting and you will catch photographs your reflexes would have fired straight past.", "url": "/protocol-012.html", "access": "free", "topics": ["composure", "seeing", "habits"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Protocol 001: The 3-Second Reset", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/media/protocol-cards/protocol-012.png"}, {"id": "protocol-013", "type": "protocol", "title": "Protocol 013: How to Price Your First 10 Clients", "questions": ["How much should I charge my first paying clients?", "I'm undercharging for shoots and ending up broke, how do I set a rate?", "How do I price photography when I'm just starting out?"], "shortAnswer": "Price with math, not worth: every hour of shooting costs roughly three hours total once editing, admin, and delivery count, so your rate has to survive being divided by three. Set one honest price for your first 10 clients, say it out loud without apologizing, then raise it; starting cheap only buys you cheap clients who refer more cheap clients.", "url": "/protocol-013.html", "access": "free", "topics": ["pricing", "clients", "business"], "level": "pro", "brand": "", "model": "", "leadsTo": "Protocol 008: The 3-Quote Rule", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-013.png"}, {"id": "protocol-014", "type": "protocol", "title": "Protocol 014: What to Buy First (When You Have $500)", "questions": ["I have $500 saved, what camera gear should I buy first?", "How do I decide what gear to buy next?", "Should I buy the best-reviewed gear I can afford?"], "shortAnswer": "Buy the thing that removes a specific block, not the best-reviewed thing you can afford. Name the bottleneck in one sentence, the shot you keep missing for a concrete reason; if you cannot name it, you do not have a gear problem and the $500 stays in your pocket.", "url": "/protocol-014.html", "access": "free", "topics": ["gear", "buying", "decisions"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Protocol 017: When the Upgrade Is Actually Worth It", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-014.png"}, {"id": "protocol-015", "type": "protocol", "title": "Protocol 015: Using AI for Culling: What Actually Works", "questions": ["Can AI cull my wedding photos for me?", "What are AI culling tools actually good at?", "I have thousands of photos to sort after a wedding, how can AI help without ruining my picks?"], "shortAnswer": "Use AI culling for rejection, never for selection. It reliably removes the technical failures, blinks, motion blur, misfires, and near-duplicates, roughly 60 percent of a big shoot's dead weight; it cannot judge which imperfect frame matters emotionally, so the choosing still has to be yours.", "url": "/protocol-015.html", "access": "free", "topics": ["ai", "culling", "workflow", "weddings"], "level": "pro", "brand": "", "model": "", "leadsTo": "AI Workbench", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-015.png"}, {"id": "protocol-016", "type": "protocol", "title": "Protocol 016: The Post-Shoot Email That Books the Next Gig", "questions": ["How do I get past clients to book me again and send referrals?", "My clients love their photos but never refer anyone, what's missing?", "What email should I send after delivering a gallery?"], "shortAnswer": "Great photos get admired, not forwarded; referrals happen when you ask at the right moment. About 48 hours after delivery, while clients are still showing the photos around, send one short email: thanks, one specific memory from the shoot, and one clear ask. Three sentences is the whole machine.", "url": "/protocol-016.html", "access": "free", "topics": ["clients", "referrals", "email", "business"], "level": "pro", "brand": "", "model": "", "leadsTo": "Deliver (client galleries)", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-016.png"}, {"id": "protocol-017", "type": "protocol", "title": "Protocol 017: When the Upgrade Is Actually Worth It", "questions": ["How do I know if I really need a new camera or I'm just bored of mine?", "When is upgrading my camera actually worth the money?", "Should I buy the new camera body everyone's reviewing?"], "shortAnswer": "An upgrade is worth it only when your current camera blocks a specific shot on real work, one you actually missed, more than once; boredom disguises itself as a gear problem because shopping feels like progress. Test it by renting the new body for one real job: if it earns its keep, buy it; if the job goes fine either way, you just saved thousands.", "url": "/protocol-017.html", "access": "free", "topics": ["gear", "upgrading", "decisions"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Protocol 014: What to Buy First (When You Have $500)", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-017.png"}, {"id": "protocol-018", "type": "protocol", "title": "Protocol 018: The Editing Automation Stack", "questions": ["Editing a wedding takes me hours, how do I speed it up without looking generic?", "How do I automate the boring parts of photo editing?", "I edit every photo one by one and it's killing my hourly rate, what do I change?"], "shortAnswer": "About 80 percent of wedding editing is repetition: same venue light, same skin tones, same corrections hundreds of times. Let an automation stack handle that repeatable 80 percent and keep your hands on the 20 percent that carries your style; automating the labor saves about 2 hours a wedding, and the generic look only comes from automating taste.", "url": "/protocol-018.html", "access": "free", "topics": ["editing", "automation", "workflow", "weddings"], "level": "pro", "brand": "", "model": "", "leadsTo": "Field Manual No. 02: The Finish", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-018.png"}, {"id": "protocol-019", "type": "protocol", "title": "Protocol 019: Real Estate Protocols: The First 5 Shots", "questions": ["How do I shoot a real estate listing so the agent hires me again?", "How many photos should a real estate listing have, and in what order?", "My listing galleries feel like random angles, how do I fix that?"], "shortAnswer": "Shoot the listing as a five-shot story in walking order, the way a buyer would walk through the door: the hero, the flow, the anchor, the life, the detail. Twelve sequenced frames read as a tour; forty random angles read as homework, and the first frame decides whether anyone sees a second.", "url": "/protocol-019.html", "access": "free", "topics": ["real estate", "listings", "business"], "level": "pro", "brand": "", "model": "", "leadsTo": "Deliver (client galleries)", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-019.png"}, {"id": "protocol-020", "type": "protocol", "title": "Protocol 020: Wedding Day: The 30-Second Venue Read", "questions": ["I walk into a wedding venue I've never seen, how do I know where to shoot?", "How do I read a new venue fast on a wedding day?", "I keep shooting getting-ready photos in bad light because I didn't look around first, how do I stop?"], "shortAnswer": "Every venue answers three questions in about 30 seconds: where is the light, where is the background, and where can you not stand. Light tells you where faces go, backgrounds tell you where the camera goes, and the limits tell you how the day will run; read those first and you never shoot blind.", "url": "/protocol-020.html", "access": "free", "topics": ["weddings", "venues", "light"], "level": "pro", "brand": "", "model": "", "leadsTo": "Protocol 002: Protect the Shot", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-020.png"}, {"id": "protocol-021", "type": "protocol", "title": "Protocol 021: Sports: The Autofocus That Actually Follows", "questions": ["Why does my camera track the background instead of the player in sports?", "What autofocus settings work for sports photography?", "How do I freeze fast action sharp in sports photos?"], "shortAnswer": "All focus points means all guesses: the camera locks onto the highest-contrast thing in the frame, which at a sports field is usually the background. Shrink its choices to a tight zone of focus points, use continuous autofocus that stays locked on, and shoot at 1/1000 of a second or faster to freeze the athletes; the ball and the fastest swings can still blur there and may need 1/2000.", "url": "/protocol-021.html", "access": "free", "topics": ["sports", "autofocus", "tracking", "shutter speed"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Camera Select autofocus lessons", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/media/protocol-cards/protocol-021.png"}, {"id": "protocol-022", "type": "protocol", "title": "Protocol 022: The Blue Hour Contract", "questions": ["How do I get those deep blue photos right after sunset?", "What is blue hour and how do I plan for it?", "My blue hour photos never look magical, do I need better gear?"], "shortAnswer": "Blue hour is the roughly eleven minutes after sunset when the sky turns deep blue and the city lights come on, and it rewards people who arrive with a plan instead of hope. This Pro protocol argues it is not a gear problem or a lucky accident: fumbling with settings or firing off frames and hoping burns the whole window, so the deciding work happens before the sky turns.", "url": "/protocol-022.html", "access": "pro", "topics": ["blue hour", "night", "sunset", "planning"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Pro (Protocol 022 is Pro-gated)", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/media/protocol-cards/protocol-022.png"}, {"id": "blog-adobe-camera-raw-grid-view", "type": "article", "title": "Camera Raw's New Grid View Is the Catalog-Free Workflow You Already Own", "questions": ["Can I cull and rate photos in Camera Raw without a Lightroom catalog?", "How does Camera Raw's new grid view work?", "What is exposure matching in Camera Raw?", "Do my ratings survive if I move the folder to another drive?"], "shortAnswer": "Yes. Camera Raw now opens a folder of raw files as a grid with star ratings, color labels, rejects, and filters, and your picks are written to small XMP sidecar files next to the photos, so they survive drive and computer changes with no catalog database. Its new exposure matching can match a set of photos to the first one you click, either by camera settings alone or by settings plus the ambient light reading your camera recorded.", "url": "/blog/adobe-camera-raw-grid-view.html", "access": "free", "topics": ["editing workflow", "culling", "camera raw", "lightroom"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Develop Lab", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/adobe-camera-raw-grid-view.jpg"}, {"id": "blog-ai-school-photos", "type": "article", "title": "Parents Are Using AI for School Photos Instead of Photographers", "questions": ["Are parents using AI instead of school photographers?", "How are parents making AI school photos?", "Is AI taking work from school photographers?", "How do I build a photography business AI cannot replace?"], "shortAnswer": "Yes. Some parents photograph their children against a plain backdrop and use AI to add the standard school-portrait backdrop and styling, skipping the $25 to $60 print package, and 58% of U.K. photographers surveyed by the Association of Photographers say they have lost commissioned work to AI. The article's answer for photographers is to sell the experience and trust around a real portrait, not the backdrop and template AI now does for free.", "url": "/blog/ai-school-photos.html", "access": "free", "topics": ["ai", "school photography", "business", "portraits"], "level": "pro", "brand": "", "model": "", "leadsTo": "Protocol 013: How to Price Your First 10 Clients", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/ai-school-photos.jpg"}, {"id": "blog-aop-emerging-talent-awards-2026", "type": "article", "title": "An Award Only for Photographers Under Three Years In. These Winners Are Worth Studying", "questions": ["Can a new photographer win a real photography award?", "Who won the AOP Emerging Talent Awards 2026?", "What makes an award-winning photo project stand out?", "What can beginners learn from award-winning photographers?"], "shortAnswer": "Yes. The AOP Emerging Talent Awards are open only to photographers with less than three years of practice, and the 2026 gold winner rigged a 57-metre highline across a melting Icelandic glacier to make its yearly retreat visible at human scale. The lesson from both winning projects is that they won on commitment to an idea, time, and planning, not technique alone; the camera was the last step, not the first.", "url": "/blog/aop-emerging-talent-awards-2026.html", "access": "free", "topics": ["awards", "beginners", "photo projects", "documentary"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/aop-emerging-talent-awards-2026.jpg"}, {"id": "blog-apple-reference-image-proves-photos-real", "type": "article", "title": "Apple Built a Quantum-Proof Way to Prove a Photo Is Real. Here Is How It Works", "questions": ["How does Apple Reference Image prove a photo is real?", "What is the difference between Apple Reference Image and C2PA?", "Can a photo be signed as real at the moment it is taken?", "Why is C2PA not enough to prove a photo is authentic?"], "shortAnswer": "Apple Reference Image is an opt-in mode on the iPhone 18 Pro that signs the raw pixel data in the sensor hardware the instant you shoot, before the operating system can touch it, then develops and signs the file in Apple's Private Cloud Compute with a post-quantum signature. C2PA works the other way: it stamps a file's history at the end of the chain, so fake pixels could be injected before the first stamp exists, though it is an open standard supported across Sony, Adobe, Samsung, and Google.", "url": "/blog/apple-reference-image-proves-photos-real.html", "access": "free", "topics": ["authenticity", "ai", "c2pa", "iphone"], "level": "intermediate", "brand": "Apple", "model": "iPhone 18 Pro", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/apple-reference-image-proves-photos-real.jpg"}, {"id": "blog-autumn-foliage-lightroom-edit", "type": "article", "title": "How to Edit Autumn Foliage Without Overcooking It", "questions": ["How do I edit autumn foliage in Lightroom without overdoing it?", "Why do my fall color edits look neon?", "Should I use the saturation slider on fall photos?", "How do I make autumn leaves glow in an edit?"], "shortAnswer": "Leave the global saturation and vibrance sliders alone; warm hues clip and smear fast, which is what turns fall edits neon. The workflow in the article lifts shadows and whites slightly, adds texture, sets clarity around minus 20, then does the real work per color in the mixer, checking which colors are actually in the frame and muting the off-season ones so red, orange, and yellow carry the image.", "url": "/blog/autumn-foliage-lightroom-edit.html", "access": "free", "topics": ["editing", "lightroom", "autumn", "color"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Develop Lab", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/autumn-foliage-lightroom-edit.jpg"}, {"id": "blog-bad-light-street-photography", "type": "article", "title": "Is There Such a Thing as Bad Light in Street Photography?", "questions": ["Is flat gray light bad for street photography?", "Should I only shoot street photos at golden hour?", "How do I take good street photos on an overcast day?", "What makes a street photo hold up without good light?"], "shortAnswer": "No. Peter Forsgard argues golden light can hide whether a street photo actually has anything happening in it, while flat, overcast light is a revealer: with no shadows or rim light to lean on, the frame either has a story, a gesture, or a juxtaposition, or it does not. Overcast days also hold exposure steady, give richer colors without glare, and make rain, reflections, and umbrellas work in your favor.", "url": "/blog/bad-light-street-photography.html", "access": "free", "topics": ["street photography", "light", "composition", "overcast"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/bad-light-street.jpg"}, {"id": "blog-bayer-filter-colorblind-sensor", "type": "article", "title": "Your Camera's Sensor Is Colorblind. Here Is How It Fakes Color", "questions": ["How does my camera sensor see color if it only records brightness?", "What is a Bayer filter on a camera sensor?", "What is demosaicing in a raw file?", "Why do raw files look different in different converters?"], "shortAnswer": "Each photosite on your sensor records only one number: how much light it collected, with no color label. Color comes from the Bayer mosaic, a filter pattern bonded over the sensor with two green filters for every red and blue, matching how human vision leans on green. Because each point records only one color, the converter has to estimate the other two from neighboring points, a step called demosaicing, and different converters guess differently, which is why raw files differ between apps.", "url": "/blog/bayer-filter-colorblind-sensor.html", "access": "free", "topics": ["sensors", "raw files", "color", "how cameras work"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/bayer-filter-colorblind-sensor.jpg"}, {"id": "blog-beauty-dish-vs-softbox", "type": "article", "title": "How to Tell a Beauty Dish From a Softbox Just by Looking at the Photo", "questions": ["How can I tell what light modifier was used in a portrait?", "What is the difference between a beauty dish and a softbox?", "How do I work out how a portrait was lit?", "What do highlights on skin tell me about the light?"], "shortAnswer": "Read the portrait like evidence: shadows under the chin and nose show where the light stood, and the bright highlights on skin show the modifier, since a smaller effective source makes highlights on the forehead, lips, and nose tighter and brighter with more contrast. Side by side, a beauty dish shows more of that shiny bite on forehead and lips, while a big octabox looks milkier and flatters unretouched skin; distance matters too, because a large source pulled far back behaves like a smaller, harder one.", "url": "/blog/beauty-dish-vs-softbox.html", "access": "free", "topics": ["lighting", "portraits", "beauty dish", "softbox"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/beauty-dish-vs-softbox.jpg"}, {"id": "blog-blue-planet-iii-murky-footage-ai-proof", "type": "article", "title": "Blue Planet III Is Keeping the Murky Shots to Prove It Is Real", "questions": ["Why is Blue Planet III keeping imperfect underwater shots?", "Did Blue Planet III use AI in its footage?", "How do imperfections prove a photo or video is real?", "What new cameras did the Blue Planet III crew build?"], "shortAnswer": "Because AI can now generate a flawless reef in seconds, a flawless reef no longer proves anything, so Blue Planet III deliberately keeps murky water, plankton, haze, and boats in frame as proof of real photography, and the BBC states no generative AI was used in any frame. The crew also built new tools for rarely filmed behaviour, including a mini-dome camera for octopuses and an underwater CCTV-style stonefish camera.", "url": "/blog/blue-planet-iii-murky-footage-ai-proof.html", "access": "free", "topics": ["nature filming", "ai", "authenticity", "underwater"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/blue-planet-iii-murky-footage-ai-proof.jpg"}, {"id": "blog-boredom-street-photography", "type": "article", "title": "Why Boredom Might Be the Best Thing for Your Street Photography", "questions": ["Why do I come home from street photography with no good photos?", "How do I stay sharp when nothing is happening on the street?", "What is a panic shot in street photography?", "How much of street photography is just waiting?"], "shortAnswer": "Most of it: Peter Forsgard puts street photography at 95% waiting, and says the slow stretches are where your eye gets trained rather than time wasted. Take deliberate warm-up shots early, head out with an idea or ongoing project for the quiet hours, and watch for the panic shots that come when boredom makes you walk faster and shoot just to have something on the card; staying bored sharpens attention.", "url": "/blog/boredom-street-photography.html", "access": "free", "topics": ["street photography", "patience", "practice", "mindset"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/boredom-street-photography.jpg"}, {"id": "blog-brands-future-visions", "type": "article", "title": "Canon, Nikon, Sony and Fujifilm Each See Your Future Differently", "questions": ["What is Canon's plan for the future of its cameras?", "What is Nikon's plan for its Z cameras?", "Where do Canon, Nikon, Sony, and Fujifilm each think photography is headed?", "Why are young people buying compact cameras?"], "shortAnswer": "Each brand named a different bet in Nikkei interviews: Canon says young buyers choose compact cameras for the shooting experience, not top specs, and plans to grow its video-oriented V-series and video lenses; Nikon says it is still working on bringing flagship Z9 features down to cheaper models while investing in new processing engines, sensors, and video cameras. Sony's stated direction is Spatial AI, and Fujifilm is doubling down on the joy of the dial.", "url": "/blog/brands-future-visions.html", "access": "free", "topics": ["camera industry", "canon", "nikon", "future"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/brands-future-visions.jpg"}, {"id": "blog-camera-prices-worth-it-not-greedy", "type": "article", "title": "High Camera Prices Are Not Proof Camera Makers Are Greedy", "questions": ["Why are new cameras so expensive?", "Are camera makers just being greedy with prices?", "How should I judge whether a camera is worth its price?", "Why do launch prices seem so high?"], "shortAnswer": "DPReview's Dale Baskin argues the higher prices reflect what it now costs to design and build cameras, not a sudden new appetite for profit, since makers wanted top prices a decade ago too and camera making is not a gold mine, as Olympus's exit and Samsung's walk-away show. His reframe for buyers: launch prices are opening bids, so stop asking why makers are greedy and ask whether the camera is worth it to you.", "url": "/blog/camera-prices-worth-it-not-greedy.html", "access": "free", "topics": ["camera prices", "buying", "industry", "gear"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/camera-prices-worth-it-not-greedy.jpg"}, {"id": "blog-camera-sales-slump-compacts-rise", "type": "article", "title": "Camera Sales Are Slipping. Compact Cameras Are Not.", "questions": ["Are compact cameras selling better than mirrorless cameras?", "What do the latest camera sales figures show?", "Why are compact cameras growing while other cameras fall?", "How many cameras were shipped in August 2026?"], "shortAnswer": "The split is real: CIPA figures for August 2026 show fixed-lens compact shipments up about 32% year on year at roughly 243,000 units, while interchangeable-lens cameras fell about 13% to roughly 436,800; it was interchangeable-lens shipments that had fallen four straight months, with total shipments roughly flat. Compacts cost less than a mirrorless body, fit in a jacket pocket so they are actually carried, and are often bought by younger first-time camera buyers as an object in itself.", "url": "/blog/camera-sales-slump-compacts-rise.html", "access": "free", "topics": ["camera sales", "compact cameras", "industry", "mirrorless"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/camera-sales-slump-compacts-rise.jpg"}, {"id": "blog-canon-camera-connect-app", "type": "article", "title": "Canon's Phone App Is One of the Best. That Bar Is Low.", "questions": ["Is Canon's Camera Connect app any good?", "How do I connect my Canon camera to my phone?", "Can I transfer raw files with Canon Camera Connect on Android?", "What can I control with Canon remote live view shooting?"], "shortAnswer": "It is one of the better camera phone apps, but with quirks: you must create a Canon ID first, iOS asks you to approve the camera's Wi-Fi connection every time, and file transfer splits by platform, since iOS moves JPEG, HEIF, or raw files while Android is JPEG-only and converts on the camera. Remote live view lets you change exposure settings, drive mode, AF mode, and white balance, and the article's best trick for moving files is simply a USB cable.", "url": "/blog/canon-camera-connect-app.html", "access": "free", "topics": ["canon", "phone app", "file transfer", "remote shooting"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/canon-camera-connect-app.jpg"}, {"id": "blog-canon-camera-prices-2027-memory-costs", "type": "article", "title": "Camera Prices Could Rise in 2027. Buy on a Plan, Not on a Panic.", "questions": ["Will Canon camera prices go up in 2027?", "Why would memory costs raise camera prices?", "Should I buy a camera now before prices rise?", "What did Canon say about memory prices on its earnings call?"], "shortAnswer": "Possibly. Canon told investors it no longer expects memory prices to fall in 2027 and that its policy is to offset higher component costs with price increases, though this is conditional and it already raised some prices in July. The article's guidance is to buy on a plan, not on a panic: buy now only if the body or lens unlocks work you are already turning down, and otherwise check what your current camera already does and price the used market.", "url": "/blog/canon-camera-prices-2027-memory-costs.html", "access": "free", "topics": ["canon", "camera prices", "buying", "gear"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Protocol 014: What to Buy First (When You Have $500)", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/canon-camera-prices-2027-memory-costs.jpg"}, {"id": "blog-chicago-cubs-photographer-season", "type": "article", "title": "1,500 Games In, the Cubs' Photographer Still Plans Every Frame Before It Happens", "questions": ["How does a team sports photographer plan shots before they happen?", "How does the Cubs photographer get photos published so fast?", "What can I learn from a pro baseball photographer?", "How do you photograph a walk-off celebration?"], "shortAnswer": "He plans every frame before it happens: Matt Dirksen, who has shot more than 1,500 games, reads the light, positions himself for each possible ending before the pitch, and maps who scores, where the celebration lands, and where the light comes from. His delivery is just as planned, bursting at 20 to 30 frames per second and sending cropped JPEGs straight from the camera over Wi-Fi so photos are often out before the first pitch of the next at-bat.", "url": "/blog/chicago-cubs-photographer-season.html", "access": "free", "topics": ["sports photography", "baseball", "workflow", "planning"], "level": "pro", "brand": "", "model": "", "leadsTo": "Protocol 021: Sports: The Autofocus That Actually Follows", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/chicago-cubs-photographer-season.jpg"}, {"id": "blog-client-told-photographer-charge-more", "type": "article", "title": "A Client Had to Tell This Photographer She Was Charging Too Little", "questions": ["How do I know if I am charging too little for photography?", "Why do self-taught photographers underprice their work?", "How do I work out my minimum rate as a photographer?", "What is a cost of doing business calculator for photographers?"], "shortAnswer": "Underpricing is usually a missing calculation, not a lack of confidence: working in isolation, with no mentor or peers, there is nobody to say a rate is far below the market, as happened when a client told Laura BC her 250-pound music shoot was far under the 3,000 pounds another photographer earned for comparable work. Start with costs, using a free cost-of-doing-business calculator like the NPPA's, where your gear, insurance, software, rent, and realistic billable days give you the floor you must charge to stay afloat.", "url": "/blog/client-told-photographer-charge-more.html", "access": "free", "topics": ["pricing", "business", "clients", "freelance"], "level": "pro", "brand": "", "model": "", "leadsTo": "Protocol 013: How to Price Your First 10 Clients", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/client-told-photographer-charge-more.jpg"}, {"id": "blog-commonwealth-games-kit", "type": "article", "title": "Four Cameras, Seven Lenses — and Every One Earns Its Place", "questions": ["Why do sports photographers carry three or four camera bodies?", "What lenses does a Commonwealth Games photographer carry?", "How do I choose a kit for a big sports event?", "What does a 400mm lens with a built-in teleconverter do?"], "shortAnswer": "Speed and certainty: following an athlete through a zoom, the action can suddenly move closer than the lens allows, and a second body with another focal length ready means no lens change, which matters even more in heavy rain. The kit is picked as answers to questions asked before the event, how far, how fast, how wide, and what if it rains, not as a shopping list, and most days only three of the four bodies actually went to the venues.", "url": "/blog/commonwealth-games-kit.html", "access": "free", "topics": ["sports photography", "gear", "lenses", "events"], "level": "pro", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/commonwealth-games-kit.jpg"}, {"id": "blog-custom-camera-settings-workflow", "type": "article", "title": "The Most Important Camera Setting You're Probably Not Using", "questions": ["What are the C1, C2, and C3 custom modes on my camera for?", "How do I save a whole camera setup to recall it instantly?", "How should I set up custom modes for studio and location work?", "What settings does a custom mode actually save?"], "shortAnswer": "Each custom mode saves an entire camera state: exposure mode, shutter speed and aperture, ISO behaviour, autofocus mode, drive mode, white balance, and picture profile, and turning the dial recalls the whole setup at once. Working examples from the article include one slot for strobe work at sync speed with single-shot drive and daylight white balance, another for ambient light with auto ISO and continuous autofocus, plus street and tripod slots, so changing setups stops meaning minutes of menu work.", "url": "/blog/custom-camera-settings-workflow.html", "access": "free", "topics": ["custom modes", "camera settings", "workflow", "setup"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Camera Select lessons", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/custom-camera-settings-workflow.jpg"}, {"id": "blog-depth-without-wide-aperture", "type": "article", "title": "Depth Is Not the Blur", "questions": ["How do I get depth in a photo without a wide aperture?", "Can a photo look three-dimensional at f/8?", "Is background blur the only way to separate a subject?", "Why does my blurred background no longer look special?"], "shortAnswer": "Yes, and Max Kent calls a wide aperture the lazy version of depth, since phones now fake blur in software and it no longer proves anything. Build depth with light and layers instead: soft light from roughly 45 degrees above and to the side so bands of light and shadow alternate through the frame, plus a clear foreground, midground, and background, and you get convincing separation even at f/8.", "url": "/blog/depth-without-wide-aperture.html", "access": "free", "topics": ["depth", "aperture", "light", "composition"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/depth-without-wide-aperture.jpg"}, {"id": "blog-diffraction-f16-sharpness", "type": "article", "title": "Why f/16 Makes Every Photo a Little Softer", "questions": ["Why do my photos get softer at f/16?", "What is diffraction in photography?", "Is there an aperture where sharpness suddenly drops?", "Should I avoid f/16 and f/22 for landscapes?"], "shortAnswer": "Diffraction is physics, not a lens flaw: as the aperture shrinks, light spills sideways and every point of light becomes a small blur spot, so contrast declines smoothly with every stop from your widest aperture, with no sudden cliff. An f/16 file can look measurably soft at 100% on screen yet still hold all the detail a 16 by 20 inch print needs, so whether to stop down depends on how the photo will actually be viewed.", "url": "/blog/diffraction-f16-sharpness.html", "access": "free", "topics": ["aperture", "sharpness", "diffraction", "landscape"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/diffraction-f16.jpg"}, {"id": "blog-dji-insta360-outship-mirrorless", "type": "article", "title": "Two Companies Now Ship Twice as Many Cameras as the Entire Mirrorless Market", "questions": ["Are DJI and Insta360 really shipping more cameras than mirrorless?", "Is the mirrorless camera market dying?", "What is a handheld smart camera and how is it different from a mirrorless camera?"], "shortAnswer": "DJI and Insta360 together ship more than twice as many handheld smart cameras (action, 360, and gimbal cameras) as all mirrorless makers combined, with DJI taking about three in four of them in the second quarter of 2026. Mirrorless is not collapsing: makers shipped slightly fewer bodies but the total value went up, so they are selling fewer cameras at higher prices and putting margin ahead of volume.", "url": "/blog/dji-insta360-outship-mirrorless.html", "access": "free", "topics": ["camera industry", "mirrorless market", "action cameras"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/pocket-action-camera.jpg"}, {"id": "blog-elephant-grief-wildlife-photographer-year", "type": "article", "title": "The Photo That Won Wildlife Photographer of the Year Is About Grief, Not Gear", "questions": ["What photo won Wildlife Photographer of the Year 2026?", "How did the photographer find the elephants for the winning photo?", "What matters more in wildlife photography, gear or fieldcraft?"], "shortAnswer": "Federico Veronesi's black-and-white image of a mother elephant carrying her dead calf in Namibia won the grand title. He found the family by reading drag marks in a dry riverbed and following them. The lesson the article draws is that the winning frame came from tracking, patience, and reading sign, not from better gear.", "url": "/blog/elephant-grief-wildlife-photographer-year.html", "access": "free", "topics": ["wildlife photography", "fieldcraft", "photo awards"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/elephant-grief-wildlife-photographer-year.jpg"}, {"id": "blog-entry-level-camera-is-dead", "type": "article", "title": "The Entry-Level Camera Is Dead. Your First Camera Can Be a Real One.", "questions": ["Should my first camera be the cheapest entry-level one I can find?", "Are entry-level cameras still deliberately limited for beginners?", "How do I choose a first camera I will not outgrow in a year?"], "shortAnswer": "Camera makers have stopped selling beginners deliberately pared-down cameras with yesterday's technology; recent models like the OM System PEN, Panasonic Lumix L10, and Nikon Z5IIC give first-time buyers real capability instead. The article's advice is to stop asking for the cheapest camera to learn on and pick one you can grow into, because a limited camera teaches you its limits, not photography.", "url": "/blog/entry-level-camera-is-dead.html", "access": "free", "topics": ["first camera", "buying a camera", "mirrorless"], "level": "beginner", "brand": "", "model": "", "leadsTo": "The Camera Confidence Guide", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/entry-level-camera-is-dead.jpg"}, {"id": "blog-entry-level-mirrorless-football-shoot", "type": "article", "title": "Top-Flight Football on an Entry-Level Camera", "questions": ["Can an entry-level camera like the Canon EOS R50 shoot top-flight football?", "What autofocus settings should I use for football?", "How do I stop other players passing in front from stealing my focus?"], "shortAnswer": "A photography student using her own Canon EOS R50 came home with pro-worthy shots shadowing a club photographer who used a pro body. The three autofocus moves that mattered were setting subject detection for the right subject, using Servo or Continuous AF, and turning the sensitivity down so players passing between her and the subject would not yank focus off; an AF Stop button on the lens also kept focus from running to the background.", "url": "/blog/entry-level-mirrorless-football-shoot.html", "access": "free", "topics": ["sports photography", "autofocus", "football"], "level": "intermediate", "brand": "Canon", "model": "EOS R50", "leadsTo": "Protocol 021: Sports — The Autofocus That Actually Follows", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/entry-level-football-shoot.jpg"}, {"id": "blog-every-flash-photo-two-exposures", "type": "article", "title": "Every Flash Photo Is Really Two Exposures", "questions": ["Why do my memorized flash settings stop working when the room changes?", "How do I balance flash with the light already in the room?", "In what order should I set my camera and flash for a portrait?"], "shortAnswer": "Every flash photo is two exposures: set the room light with the camera, then set the subject with the strobe, and never let the two argue. JC Carey's order never changes: ISO, focal length, aperture, shutter speed, then the light. When the subject comes out too dark, he turns the strobe up instead of opening the aperture, so his depth of field decision stays intact.", "url": "/blog/every-flash-photo-two-exposures.html", "access": "free", "topics": ["flash", "strobe", "exposure"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/every-flash-photo-two-exposures.jpg"}, {"id": "blog-fall-color-shot-list", "type": "article", "title": "Twenty Years of Fall Color, One Shot List", "questions": ["What kinds of photos should I plan for fall color season?", "How should the weather forecast change what I shoot in autumn?", "What should I shoot on an overcast fall day?"], "shortAnswer": "Build a shot list for the whole season before you leave home: vistas, waterfalls, wildlife small in the landscape and in tighter portraits, macro leaves, textures, barns and covered bridges, and abstracts or reflections. Then let the conditions pick the type for the day: overcast light suits waterfalls and macro like a giant softbox, while partly cloudy sunrise or sunset weather suits the big vistas.", "url": "/blog/fall-color-shot-list.html", "access": "free", "topics": ["fall photography", "landscape", "shoot planning"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/fall-color-shotlist.jpg"}, {"id": "blog-fiery-sunset-landscape-photo", "type": "article", "title": "You Don't Need a Fiery Sunset to Make a Great Landscape Photo", "questions": ["Do I need a dramatic sunset to make a good landscape photo?", "What landscape subjects shoot well on an overcast day?", "Why shoot ordinary places near home instead of famous viewpoints?"], "shortAnswer": "No. Craig Roberts has stopped chasing epic light and argues that pleasant, ordinary scenes near your door, shot often and learned deeply, build stronger photographers than one trip a year to a famous viewpoint. Overcast light suits woodland, waterfalls, wet rock, and autumn leaves, and with no glowing sky to carry the frame, composition, shape, and texture have to do the work.", "url": "/blog/fiery-sunset-landscape-photo.html", "access": "free", "topics": ["landscape", "light", "composition"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/fiery-sunset-landscape-photo.jpg"}, {"id": "blog-film-era-lenses-manual-discipline", "type": "article", "title": "Old Glass, Sharper Photographer", "questions": ["Why would I put old film-era lenses on a modern mirrorless camera?", "What does shooting with manual focus lenses actually teach you?", "Do vintage lenses render an image differently from modern lenses?"], "shortAnswer": "Travis Butler shoots adapted film-era lenses on a Sigma fp and Lumix S5 not for nostalgia but for training and rendering: with no autofocus or stabilization, every frame forces you to choose the aperture and place the focal plane yourself. He credits a decade of that discipline with teaching him what the plane of focus actually does, and says the old lenses give vivid color and rich tonal gradation that technically perfect modern lenses often lose.", "url": "/blog/film-era-lenses-manual-discipline.html", "access": "free", "topics": ["vintage lenses", "manual focus", "aperture"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/film-era-lenses-manual-discipline.jpg"}, {"id": "blog-find-compositions-overwhelming-location", "type": "article", "title": "How to Find Compositions When the Location Overwhelms You", "questions": ["How do I find a composition when a beautiful location is overwhelming?", "What are compositional blinders and how do they help?", "Should I use an in-camera crop mode to help me compose?"], "shortAnswer": "Use constraints that cut the scene down until a picture shows up: close the rear screen and work only through the viewfinder, use a long lens so context drops away and patterns show, or pick one in-camera crop mode for the outing. The advice is to choose one constraint per outing, and to check your camera first, because some cameras crop the RAW file for good while others keep the full sensor area to change your mind later.", "url": "/blog/find-compositions-overwhelming-location.html", "access": "free", "topics": ["composition", "travel photography", "constraints"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/find-compositions-overwhelming-location.jpg"}, {"id": "blog-first-print-darkroom", "type": "article", "title": "What Your First Print Will Teach You About Your Own Photos", "questions": ["What can making a print teach me that looking at a screen cannot?", "Why do flaws look worse on screen than in a finished print?", "How can printing a photo help me shoot it better next time?"], "shortAnswer": "Making his first real darkroom print forced a DPReview writer to sit with one favorite photograph in a way screen viewing never did. He noticed new things in the print, while the softness he obsessed over at 1:1 zoom on the monitor was barely obvious at real viewing size. Spending that long with one image makes you ask what you would do differently if you shot it again.", "url": "/blog/first-print-darkroom.html", "access": "free", "topics": ["printing", "darkroom", "reviewing your work"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/first-print-darkroom.jpg"}, {"id": "blog-first-starlapse-timelapse", "type": "article", "title": "What a Star Timelapse Actually Teaches You About Gear", "questions": ["Do I need a star tracker to shoot a star timelapse?", "What gear does a night sky timelapse actually take?", "Will the stars blur in a 15 second exposure without tracking?"], "shortAnswer": "Less gear than you think. In a New Mexico test the iOptron SkyTracker Pro did its tracking job, but even after a loose ball head let the camera swing down mid-sequence it barely mattered, because the test used a relatively fast 15-second shutter where the Earth's rotation barely registers and the stars still looked sharp.", "url": "/blog/first-starlapse-timelapse.html", "access": "free", "topics": ["astrophotography", "timelapse", "night sky"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/first-starlapse-timelapse.jpg"}, {"id": "blog-focus-stacking-jumping-spider", "type": "article", "title": "A 5mm Spider, Shot 20 Times Life Size — and Sharp in Every Hair", "questions": ["What is focus stacking and why do macro photographers use it?", "Why can only a thin slice of a macro subject be sharp in one frame?", "How do you get a tiny spider sharp everywhere in one portrait?"], "shortAnswer": "At 20 times life size, depth of field shrinks to a sliver, so one frame can only hold a thin slice of the spider sharp. John-Oliver Dum works with that instead of fighting it: he shoots dozens of frames, sometimes more than 100, each focused a fraction deeper than the last, then merges them into a single pin-sharp portrait.", "url": "/blog/focus-stacking-jumping-spider.html", "access": "free", "topics": ["macro photography", "focus stacking", "depth of field"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/focus-stacking-jumping-spider.jpg"}, {"id": "blog-getty-bankruptcy-contributors-playbook", "type": "article", "title": "Getty Is Going Private Through Bankruptcy. Here Is What Photographers Should Do Now", "questions": ["What does Getty Images going through bankruptcy mean for contributors?", "What should stock photographers do right now about the Getty restructuring?", "Do I still own my copyright if I license through Getty?"], "shortAnswer": "Getty announced a prepackaged Chapter 11 restructuring to take the company private, backed by up to $533 million in new equity. Getty says there is no anticipated impact on contributors, but nothing is court-approved yet, so photographers who earn from stock should document what they are owed starting now. You still own your copyright, but Getty may hold licensing rights under your agreement, so review your contract before acting and do not treat the news as permission to ignore exclusivity clauses.", "url": "/blog/getty-bankruptcy-contributors-playbook.html", "access": "free", "topics": ["stock photography", "business", "licensing"], "level": "pro", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/getty-bankruptcy-photographers.jpg"}, {"id": "blog-godox-im10-25-dollar-flash", "type": "article", "title": "A $25 Flash Is the Cheapest Photography Lesson You Can Buy", "questions": ["Can a very cheap manual flash teach me how flash works?", "What is the Godox iM10 mini flash and what can it not do?", "Why is a flash with no automatic mode a better teacher for beginners?"], "shortAnswer": "The Godox iM10 costs $24.90, weighs 23 grams, and offers four manual power levels and nothing else: no TTL, no tilt or bounce, and no off-camera use. That is the point for learning: an automatic flash guesses for you, while four manual levels force you to think in ratios, one stop more or less and what each step does to the face in front of you, and its pocket size means it actually comes with you.", "url": "/blog/godox-im10-25-dollar-flash.html", "access": "free", "topics": ["flash", "lighting", "beginner gear"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/godox-im10-25-dollar-flash.jpg"}, {"id": "blog-high-key-cranes-snow", "type": "article", "title": "How Far Can You Push Exposure Before Losing the Subject?", "questions": ["How far can I overexpose a snow scene before I lose the subject?", "How do I protect highlights when shooting white birds in snow?", "Why does my camera meter make snow scenes come out too dark?"], "shortAnswer": "Snow fools a camera meter into rendering a bright scene too dark, so some positive compensation is just correctness; this photographer pushed further, exposing right up to the edge of clipping so the world dissolved into white and only the crane remained. His method was to watch the histogram in the viewfinder in real time, protect the highlights rather than the midtones, and shoot everything in RAW because he was working so close to clipping.", "url": "/blog/high-key-cranes-snow.html", "access": "free", "topics": ["exposure", "wildlife photography", "snow", "histogram"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Exposure Lab", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/high-key-cranes-snow.jpg"}, {"id": "blog-how-many-photos-per-day", "type": "article", "title": "Take Fewer Photos. See More.", "questions": ["Is burst shooting and taking thousands of photos hurting my photography?", "Why would taking fewer photos get me better work?", "When is high frame rate shooting actually worth it?"], "shortAnswer": "James Popsys cut his daily shooting from thousands of frames to 250 on a Greenland trip and brought home better work. Overshooting costs you twice: the evening spent culling, and the presence you lose while your eye stays in the viewfinder instead of scanning the scene. Fast frame rates earn their place in wildlife and sports, but in landscape, street, and travel work the deciding factor is usually where you stand and what you include.", "url": "/blog/how-many-photos-per-day.html", "access": "free", "topics": ["shooting discipline", "culling", "burst shooting"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/how-many-photos-per-day.jpg"}, {"id": "blog-image-buyers-prefer-human-made-ai-survey", "type": "article", "title": "Two-Thirds of Image Buyers Say Human-Made Beats AI-Generated", "questions": ["Do professional image buyers prefer human-made photos over AI-generated ones?", "Are buyers rejecting AI-generated stock images?", "What did the Storyblocks survey of image buyers find?"], "shortAnswer": "Storyblocks surveyed 1,442 professionals who license stock media in July 2026: two-thirds said human-made assets are higher quality than AI-generated ones, and half had avoided or rejected AI-generated stock in the past year. Storyblocks says work made by a person carries a perspective that AI content only mimics, and that is what buyers are choosing for.", "url": "/blog/image-buyers-prefer-human-made-ai-survey.html", "access": "free", "topics": ["ai images", "stock photography", "business"], "level": "pro", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/image-buyers-prefer-human-made-ai-survey.jpg"}, {"id": "blog-image-stabilization-shaker-table", "type": "article", "title": "Your Stabilization Rating Comes From a Shaker Table, Not a Hand", "questions": ["Can I compare stabilization stop ratings between camera brands?", "How is a camera's stabilization rating actually tested?", "What part of a stabilization rating should I actually look at?"], "shortAnswer": "Stabilization ratings come from a shaker table in a controlled room, not a human hand, and each manufacturer chooses the focal length and lens for its own test, so one brand's 8.5 stops and another's 7.5 are not reliably a stop apart in your hands. The article's advice is to read the corner figure and the gap between the center and corner numbers instead, and not let the headline stops decide a purchase between bodies in the same class.", "url": "/blog/image-stabilization-shaker-table.html", "access": "free", "topics": ["stabilization", "camera specs", "buying a camera"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/image-stabilization-shaker-table.jpg"}, {"id": "blog-in-camera-presets-not-cheating", "type": "article", "title": "Why In-Camera Presets Aren't Cheating", "questions": ["Are in-camera presets and film simulations cheating?", "What can shooting with a preset teach me that shooting RAW does not?", "Should I shoot RAW plus JPEG when I use a camera preset?"], "shortAnswer": "Mike Harris argues presets are not cheating, any more than a film stock's look was cheating. Because presets are applied to JPEGs with little room to fix mistakes later, they reward getting exposure right in camera and remove the editing anxiety that leads to overediting; the live viewfinder lets you see the finished look as you compose. His suggestion is to shoot RAW plus JPEG: commit to the preset's look and keep the RAW files as backup.", "url": "/blog/in-camera-presets-not-cheating.html", "access": "free", "topics": ["presets", "film simulations", "jpeg"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 02: The Finish", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/in-camera-presets-not-cheating.jpg"}, {"id": "blog-landscape-photography-myths-questioned", "type": "article", "title": "14 Landscape Photography Beliefs Worth Questioning", "questions": ["Do I need an ultra-wide lens for landscape photography?", "Do I need to travel somewhere exotic or use a tripod for every landscape?", "Can landscape photography actually become my income?"], "shortAnswer": "Several common beliefs do not hold up: landscapes do not require an ultra-wide lens, since a long lens isolating a ridge is every bit as much a landscape, and the composition should come first, with the focal length picked to match it. Shooting handheld where a tripod cannot be set up beats coming home with no image, exotic travel is not required when a local spot visited often beats an expensive trip on fixed dates, and landscape photography is very unlikely to become your income, so treat it as a passion.", "url": "/blog/landscape-photography-myths-questioned.html", "access": "free", "topics": ["landscape", "photography myths", "lenses"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/landscape-photography-myths-questioned.jpg"}, {"id": "blog-laowa-24mm-f2-tilt-shift", "type": "article", "title": "The Fastest Tilt-Shift Ever Is a 24mm f/2 From Laowa", "questions": ["What does a tilt-shift lens actually do?", "What makes the Laowa 24mm f/2 tilt-shift different from other tilt-shift lenses?", "Who is a tilt-shift lens for, architecture or landscape?"], "shortAnswer": "A tilt-shift lens physically moves its optics: tilt swings the plane of focus so it no longer sits parallel to the sensor, and shift slides the assembly sideways so you can keep the camera level and buildings stop leaning inward. Venus Optics' Laowa 24mm f/2 claims to be the fastest tilt-shift ever built, which matters in twilight cityscapes and architectural interiors where you cannot add light; it has near-zero distortion, plus-or-minus 10 degrees of tilt and 12mm of shift. A US launch on November 5 at $1,249 has been reported but was not confirmed on Laowa's US store or B&H, and it was already selling in China for about 7,650 yuan.", "url": "/blog/laowa-24mm-f2-tilt-shift.html", "access": "free", "topics": ["tilt-shift", "lenses", "architecture"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/laowa-tilt-shift.jpg"}, {"id": "blog-laowa-acris-35mm-macro-world-first", "type": "article", "title": "A 35mm Lens That Shoots Life-Size Macro. With Autofocus.", "questions": ["Is there a wide-angle macro lens with autofocus?", "How does the Laowa Acris 35mm macro lens focus up close?", "How much does the Laowa 35mm macro lens cost?", "Which mounts does the Laowa Acris 35mm macro come in?"], "shortAnswer": "Laowa's Acris 35mm F2.8 is billed as the first full-frame 35mm lens with true 1:1 macro and autofocus, priced at $449 in the US. Up close you focus manually to get there and the motor makes the tiny, precise moves used for focus stacking; beyond half a meter it behaves like a normal fast autofocus lens.", "url": "/blog/laowa-acris-35mm-macro-world-first.html", "access": "free", "topics": ["macro", "lenses", "autofocus", "wide angle"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/laowa-acris-35mm-macro.jpg"}, {"id": "blog-life-magazine-returns-print", "type": "article", "title": "Life Magazine Is Coming Back to Print. Study the Photo Essay, Not Just the Photo.", "questions": ["Why is Life magazine coming back to print?", "What is a photo essay and why does it matter?", "How do I make a set of photos tell a story together?"], "shortAnswer": "Life returns to print on November 23 with a 250-page first issue, and the lesson is sequencing: a photo essay works because a wide establishing shot, a medium moment, and a close detail each do a job the others cannot, edited in an order that carries a story. Being brilliant in a single frame is not the same skill as making pictures work together.", "url": "/blog/life-magazine-returns-print.html", "access": "free", "topics": ["photo essay", "sequencing", "storytelling", "print"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/life-magazine-returns-print.jpg"}, {"id": "blog-lightroom-ai-open-eyes-generative-expand", "type": "article", "title": "The Finish Is a Decision", "questions": ["Can Lightroom fix closed eyes in a photo?", "What does Lightroom's Generative Expand do?", "Is it honest to use AI to expand or fix a photo?"], "shortAnswer": "Lightroom on mobile can now open closed eyes with one tap, drawing on other photos of the same person in your library, and Generative Expand stretches a photo beyond its borders to fit a different shape. The line is honesty: Expand does not recover what was outside the frame, it invents new content that was never in the scene.", "url": "/blog/lightroom-ai-open-eyes-generative-expand.html", "access": "free", "topics": ["lightroom", "editing", "ai tools", "honesty"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 02, The Finish", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/lightroom-ai-open-eyes-generative-expand.jpg"}, {"id": "blog-lightroom-classic-catalogs-explained", "type": "article", "title": "Stop Making One Lightroom Catalog Per Session", "questions": ["How many Lightroom Classic catalogs should I use?", "Should I make a new Lightroom catalog for every shoot?", "How does one catalog per year work?"], "shortAnswer": "Stop making one catalog per session: it is safest on paper but leaves your work scattered and forces constant catalog switching. A wedding photographer with about twelve years in runs one catalog per year, keeps raw files organized by year and session on an external drive, and sorts delivered photos into collections so a whole year stays searchable in one place.", "url": "/blog/lightroom-classic-catalogs-explained.html", "access": "free", "topics": ["lightroom", "catalogs", "workflow", "organization"], "level": "pro", "brand": "", "model": "", "leadsTo": "Field Manual No. 02, The Finish", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/lightroom-catalogs-explained.jpg"}, {"id": "blog-luminar-on-web-free-raw-editor", "type": "article", "title": "RAW Editing Just Moved Into Your Browser, Free to Start", "questions": ["Can I edit RAW photos in my browser for free?", "What is Luminar on Web and what does it cost?", "Do I need to install software to start editing RAW files?"], "shortAnswer": "Luminar on Web is a photo editor from Skylum that runs entirely in a browser tab and handles RAW files, with no install. The basic version is free forever and full access is a one-time $69, with tools like object removal, photo restoration, presets and LUTs, and edits that sync across devices.", "url": "/blog/luminar-on-web-free-raw-editor.html", "access": "free", "topics": ["raw editing", "browser editor", "luminar", "free tools"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Develop Lab", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/luminar-on-web-free-raw-editor.jpg"}, {"id": "blog-making-subjects-comfortable-portraits", "type": "article", "title": "Nobody Looks Good Being Watched", "questions": ["How do I keep someone relaxed during a portrait session?", "Why do my portrait subjects look tense?", "Should I start a portrait session close up or farther away?"], "shortAnswer": "Most portrait failures are tension failures, not exposure failures: a non-model who feels watched locks up and no lighting setup hides it. Start farther away so you are not inside their personal space, let trust build, and move in only as their posture loosens; with one lens, do the same with your feet, starting with full-body frames from farther back.", "url": "/blog/making-subjects-comfortable-portraits.html", "access": "free", "topics": ["portraits", "posing", "direction", "comfort"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/making-subjects-comfortable-portraits.jpg"}, {"id": "blog-marulli-speed-aviation-photography", "type": "article", "title": "Speed in a Photograph Is About Perception, Not Shutter Speed", "questions": ["How do I show speed in a photo of a moving aircraft?", "Is showing motion just about shutter speed?", "What makes a photo of a plane feel fast?"], "shortAnswer": "Speed in a photograph is about perception more than shutter speed. Aviation photographer Simone Marulli starts with energy: where the aircraft is going, its angle and position in the frame, and how the light shapes it, then chooses shutter speed for the aircraft and the light, sometimes freezing the moment and sometimes letting motion blur carry the energy.", "url": "/blog/marulli-speed-aviation-photography.html", "access": "free", "topics": ["aviation", "motion", "shutter speed", "composition"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/jets-in-flight.jpg"}, {"id": "blog-night-photography-everyday-places", "type": "article", "title": "The Gas Station You Drive Past Every Day Is a Photograph Waiting for Night", "questions": ["How do I photograph ordinary places at night?", "How should I expose a photo at night?", "Should I use auto white balance at night?"], "shortAnswer": "Night transforms ordinary places because darkness hides the clutter and leaves pools of light as subjects by isolation alone. Expose for the highlights and let the shadows go, set white balance by hand and lean into night colors like sodium orange and neon instead of flattening them, and scout locations without the camera first.", "url": "/blog/night-photography-everyday-places.html", "access": "free", "topics": ["night photography", "white balance", "exposure", "street photography"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Protocol 022: The Blue Hour Contract (Pro)", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/night-photography-everyday-places.jpg"}, {"id": "blog-night-sky-brightening-96-percent", "type": "article", "title": "The Night Sky Is Getting Brighter Every Year. Your Dark-Sky Shots Have a Deadline.", "questions": ["Is light pollution really getting worse for night photos?", "Why are dark-sky photos getting harder to take?", "How fast is the night sky getting brighter?"], "shortAnswer": "Yes, measurably. More than 51,000 citizen-science star counts found artificial sky brightness rose 9.6 percent a year from 2011 to 2022, and 10.4 percent in North America, while satellites missed it because they cannot detect the blue light white LEDs produce. A dark-sky shot on your list gets harder every year, so plan the trip now, not someday.", "url": "/blog/night-sky-brightening-96-percent.html", "access": "free", "topics": ["night sky", "light pollution", "astrophotography", "milky way"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/night-sky-brightening-96-percent.jpg"}, {"id": "blog-nikon-f1-2-trinity-after-dark", "type": "article", "title": "What f/1.2 Actually Buys You After Dark", "questions": ["Is an f/1.2 lens worth it for night photography?", "What does f/1.2 buy you that f/1.8 does not?", "Are Nikon's f/1.2 primes sharper than the f/1.8 versions?"], "shortAnswer": "For night shooting the extra stop rarely makes or breaks the exposure, because modern sensors handle high ISO so well. The real case for Nikon's f/1.2 primes is rendering: thinner depth of field, layer separation, and background blur from a comfortable distance. It varies by lens and by test: on the 85mm pair, some tests have the cheaper f/1.8 S matching or edging the f/1.2 wide open, others favour the f/1.2.", "url": "/blog/nikon-f1-2-trinity-after-dark.html", "access": "free", "topics": ["lenses", "aperture", "night photography", "depth of field"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/nikon-low-light-trinity.jpg"}, {"id": "blog-nikon-small-world-ai-disqualification", "type": "article", "title": "Nikon Stripped a $3,000 Win Over AI, and It Changes the Rules for Everyone", "questions": ["Can you be disqualified from a photo contest for using AI?", "Why did Nikon disqualify a winning competition video?", "Why should I keep my raw files for contests?"], "shortAnswer": "Yes. Nikon disqualified the winning Small World in Motion video after a re-review found it broke the competition's rule against AI-generated videos, and moved the runners-up up. The lesson for every photographer entering contests is to read the fine print and keep your unedited raw files, because the original file is the receipt that can settle a dispute.", "url": "/blog/nikon-small-world-ai-disqualification.html", "access": "free", "topics": ["contests", "ai rules", "raw files", "ethics"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/nikon-small-world-ai.jpg"}, {"id": "blog-nikon-z5iic-vs-z5ii", "type": "article", "title": "Nikon's Z5IIC Drops the Viewfinder — Should You?", "questions": ["Should I buy the Nikon Z5IIC or the Z5II?", "What is missing from the Nikon Z5IIC?", "Is a camera without a viewfinder worth the savings?"], "shortAnswer": "The Z5IIC cuts the electronic viewfinder entirely, drops to one card slot, loses the joystick, and uses a lower-resolution rear screen, while keeping the Z5II's stabilized sensor, burst rates, ports, video modes, and subject-detecting autofocus. In the US it launched at $1,399.95 against the Z5II's $1,849.95 list price, so it is the cheaper camera there; reports of the Z5II costing the same or less came from Europe. At US prices, the question is whether the viewfinder and second slot are worth the difference to you.", "url": "/blog/nikon-z5iic-vs-z5ii.html", "access": "free", "topics": ["camera buying", "viewfinder", "full frame", "nikon z"], "level": "beginner", "brand": "Nikon", "model": "Z5IIC", "leadsTo": "Protocol 014: What to Buy First (When You Have $500)", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/nikon-z5iic.jpg"}, {"id": "blog-one-light-book-light-portrait-studio", "type": "article", "title": "Turn Any Small Venue Into a Portrait Studio With One Light", "questions": ["What is a book light in portrait photography?", "How do I turn a small venue into a portrait studio with one light?", "How do I get soft light from a small strobe?"], "shortAnswer": "A book light bounces a strobe into a reflective panel, then passes that light through diffusion fabric before it reaches the subject, like the pages of an open book. Softness depends on how big the source is relative to the subject, not what you paid for it, so a sheet of foam board and a diffusion panel gets you surprisingly close to the pro setup.", "url": "/blog/one-light-book-light-portrait-studio.html", "access": "free", "topics": ["lighting", "portraits", "strobe", "soft light"], "level": "pro", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/one-light-book-light-portrait-studio.jpg"}, {"id": "blog-phone-camera-coach-frame-not-eye", "type": "article", "title": "Your Phone Can Now Coach Your Framing. It Still Cannot Teach You to See.", "questions": ["Can my phone teach me how to frame photos?", "What does Google Camera Coach do?", "Will a phone framing coach make me a better photographer?"], "shortAnswer": "Google's Camera Coach, refined on the Pixel 11 Pro, analyzes what is in frame and suggests reframes and details as you shoot, and it made its best recommendations with people. Use it as a drill, not a substitute for an eye: it cannot tell you what you were trying to say, whether the light deserved the frame, or whether a crop flatters the subject.", "url": "/blog/phone-camera-coach-frame-not-eye.html", "access": "free", "topics": ["framing", "phone photography", "coaching", "seeing"], "level": "beginner", "brand": "", "model": "", "leadsTo": "The Camera Confidence Guide", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/phone-camera-coach-frame-not-eye.jpg"}, {"id": "blog-photography-rules-worth-breaking", "type": "article", "title": "Most Photography Rules Are Old Workarounds. Learn When to Break Them.", "questions": ["Which photography rules can I break?", "Do I always have to keep ISO low?", "Can I take good photos at noon instead of golden hour?"], "shortAnswer": "Most classic rules were workarounds for limits that have moved: stabilization changed the handholding rule, and modern sensors pushed usable ISO much further. When a rule feels rigid, ask what problem it was built to solve and whether your camera still has it. Working photographers who cannot schedule around the sun shoot at noon with a polarizing filter, side light, or a silhouette and still deliver.", "url": "/blog/photography-rules-worth-breaking.html", "access": "free", "topics": ["rules", "iso", "exposure", "noon light"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/photography-rules-worth-breaking.jpg"}, {"id": "blog-photography-website-one-clear-purpose", "type": "article", "title": "Your Photography Website Needs One Job", "questions": ["What should my photography website be for?", "Can one website be my portfolio, print store, and workshop page?", "Why does my photography website feel like it is not working?"], "shortAnswer": "One homepage cannot do all of those jobs well, so pick the primary job first. A portfolio site should behave like a quiet gallery with commerce kept discreet, a workshop hub needs proof of competence plus clear logistics and registration, and a print store needs context, sizing, framing, and a straightforward checkout. Without one clear purpose, a website rarely does any single job well.", "url": "/blog/photography-website-one-clear-purpose.html", "access": "free", "topics": ["website", "business", "portfolio", "clients"], "level": "pro", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/photography-website-one-clear-purpose.jpg"}, {"id": "blog-photon-free-raw-editor", "type": "article", "title": "A Free RAW Editor That Teaches You How to Edit", "questions": ["Is there a free RAW editor that teaches you how to edit?", "Why do my RAW photos look flat?", "I shoot RAW but never learned to edit. Where do I start?"], "shortAnswer": "Photon, from Aftershoot, is a free RAW editor built for photographers who shoot RAW but never learned what the sliders do. Its AI Coach suggests what to adjust in a given photo and explains why, while the manual tools stay fully in your control. RAW files look flat straight out of camera by design, because they are meant to be processed.", "url": "/blog/photon-free-raw-editor.html", "access": "free", "topics": ["raw editing", "free editor", "learning", "sliders"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Develop Lab", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/photon-editor-desk.jpg"}, {"id": "blog-photoshop-relight-moves-light", "type": "article", "title": "Photoshop Can Now Move the Light in Your Photo", "questions": ["Can Photoshop change the lighting in a finished photo?", "How does Photoshop Relight work and what does it cost?", "When does Photoshop Relight work well and when does it fail?"], "shortAnswer": "Relight, currently in Photoshop beta, lets you reposition, soften, and recolor the lighting in a finished image, and previews are free. Every final render costs 30 generative credits and editing and rendering again costs another 30, and it works best with a clearly defined subject like a person or an interior, while removing the original light on a landscape can look like a flashlight aimed at the scene.", "url": "/blog/photoshop-relight-moves-light.html", "access": "free", "topics": ["photoshop", "lighting", "editing", "generative ai"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 02, The Finish", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/photoshop-relight.jpg"}, {"id": "blog-prints-match-your-screen", "type": "article", "title": "Why Your Prints Never Match Your Screen — and How to Fix It", "questions": ["Why do my prints look different from my screen?", "How do I get prints that match what I see on my monitor?", "What is soft proofing for printing?"], "shortAnswer": "A monitor makes light and paper reflects it, and each produces a different range of colors, so a print is never the brightest, most vivid version you saw on screen. The fix is a small chain: a calibrated monitor, soft proofing with the ICC profile for your exact printer and paper so you grade against what that paper does, and one color manager running the job, never two.", "url": "/blog/prints-match-your-screen.html", "access": "free", "topics": ["printing", "color management", "calibration", "soft proofing"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 02, The Finish", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/prints-match-screen.jpg"}, {"id": "blog-raising-blacks-lightroom-sunset-glow", "type": "article", "title": "The One Slider Move That Makes a Sunset Glow in Lightroom", "questions": ["How do I make a sunset glow in Lightroom without blowing it out?", "Why do my sunset edits go wrong?", "What does raising the blacks do in a sunset edit?"], "shortAnswer": "Raise the blacks inside a feathered sky mask instead of raising exposure: Lightroom's sky mask bleeds into the foreground, and lifting the blacks there brightens the darker areas near the sun without blowing it out, copying what a diffusion filter does. Keep color restrained and drop Lightroom's Denoise from its default of 50 down to 15 so darker areas clean up without strange patterns.", "url": "/blog/raising-blacks-lightroom-sunset-glow.html", "access": "free", "topics": ["lightroom", "sunset", "editing", "masks"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Develop Lab", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/raising-blacks-lightroom-sunset-glow.jpg"}, {"id": "blog-rim-light-vs-fill-ratio", "type": "article", "title": "Your Rim Light Isn't Weak — Your Fill Is Just Winning", "questions": ["Why does my rim light disappear when I brighten the fill?", "How do I balance rim light and fill light in the studio?", "What is a lighting ratio counted in stops?"], "shortAnswer": "Each light's brightness only reads next to the other: raise the fill two stops and a strong rim nearly vanishes, raise the rim two stops and the fill looks dark again. Change one light at a time, judge the edge and the face together, and move the other by a known number of stops. One stop of difference is a 2:1 ratio, two stops is 4:1.", "url": "/blog/rim-light-vs-fill-ratio.html", "access": "free", "topics": ["studio lighting", "rim light", "fill light", "ratios"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/rim-light-fill.jpg"}, {"id": "blog-shutter-speed-creative-choice", "type": "article", "title": "Shutter Speed Is a Creative Choice, Not a Leftover Setting", "questions": ["Should I pick my shutter speed first or last?", "What shutter speed freezes motion and what speed blurs it?", "What does each shutter speed range do to a photo?"], "shortAnswer": "Decide the motion first instead of letting the meter pick the shutter speed after aperture and ISO. Speeds at 1/1,000 and above freeze fast motion, 1/500 down to 1/125 stop most movement, and below that blur becomes a creative tool, with 1/60 a balance point and slower speeds giving streaked backgrounds or long-exposure effects.", "url": "/blog/shutter-speed-creative-choice.html", "access": "free", "topics": ["shutter speed", "exposure", "motion blur"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Exposure Lab", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/shutter-speed-creative-choice.jpg"}, {"id": "blog-sigma-50-120mm-f28-aps-c", "type": "article", "title": "Sigma's 50-120mm f/2.8 Is the APS-C Zoom We've Been Waiting For", "questions": ["Is there a good f/2.8 portrait zoom for APS-C cameras?", "What does a 50-120mm lens on APS-C cover in full frame terms?", "What are the downsides of Sigma's 50-120mm f/2.8?"], "shortAnswer": "Sigma's 50-120mm f/2.8 gives APS-C shooters the view of a 75-180mm full frame lens (80-192mm on Canon RF), the classic range for portraits, events, and sideline sports, at f/2.8 through the whole zoom. It costs $799 and comes for Sony E, Canon RF, and Fujifilm X mounts; it weighs 390 grams in E and X mount and 410 grams for Canon RF, with trade-offs in flare from bright light and softer corners wide open at the long end.", "url": "/blog/sigma-50-120mm-f28-aps-c.html", "access": "free", "topics": ["lenses", "aps-c", "portraits", "zoom"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/sigma-50-120-aps-c.jpg"}, {"id": "blog-sigma-character-lens", "type": "article", "title": "Sigma Is Selling Character Now, Not Just Sharpness", "questions": ["Why would a new lens be made with soft corners on purpose?", "What is Sigma's 50mm F1.4 CL lens?", "What does lens character mean instead of sharpness?"], "shortAnswer": "Sigma's 50mm F1.4 CL DG Contemporary is the first in a new CL line built around character rather than maximum sharpness, with corners Sigma itself describes as especially soft. It is compact and light at 375 grams (about 65mm across; roughly 54 to 56mm long depending on mount), arrives in early spring 2027 for L and Sony E mounts with no price announced, and its focus can wobble a little, making it less suited to continuous autofocus for video.", "url": "/blog/sigma-character-lens.html", "access": "free", "topics": ["lenses", "sharpness", "character", "sigma"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/sigma-character-lens.jpg"}, {"id": "blog-single-prime-lens-whole-trip", "type": "article", "title": "What Happens When You Take One Lens on a Trip", "questions": ["Should I take just one prime lens on a trip?", "What happens when you shoot with one focal length the whole trip?", "Why do fixed lens cameras keep selling out?"], "shortAnswer": "Shooting a whole trip on one prime lens gives your photos a consistent look and removes lens choices in the moment, so you spend your attention on light, timing, and the person in front of you. That is the same appeal behind fixed lens cameras like the Fujifilm X100VI, Ricoh GR III, and Leica Q3: the focal length decision is made once, at purchase.", "url": "/blog/single-prime-lens-whole-trip.html", "access": "free", "topics": ["lenses", "prime lens", "travel", "simplicity"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Protocol 010: The One Lens That Makes You a Better Photographer", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/single-prime-one-trip.jpg"}, {"id": "blog-softer-lenses-character-over-perfection", "type": "article", "title": "The Sharpest Lens Is Not Always the Best Lens. Character Is a Choice.", "questions": ["Is the sharpest lens always the best lens?", "Why can very sharp modern lenses make portraits feel flat?", "Why are lens makers building softness back into new lenses?"], "shortAnswer": "The sharpest lens is not always the best one. Sigma's retro 50mm in the new CL series deliberately keeps a gentle softness and softer rendering of texture so the subject stands out instead of the whole frame competing at the same level of bite. A lens that renders everything with equal edge-to-edge sharpness can leave a portrait with nowhere for the eye to rest.", "url": "/blog/softer-lenses-character-over-perfection.html", "access": "free", "topics": ["lenses", "sharpness", "character", "portraits"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/softer-lenses-character-over-perfection.jpg"}, {"id": "blog-sony-20-70mm-mountain-zoom", "type": "article", "title": "Sony's 20-70mm f/4 Might Be the Mountain Zoom to Beat", "questions": ["Sony 20-70mm f/4 or 24-50mm f/2.8 for hiking and climbing?", "Is an f/4 zoom good enough for mountain photography?", "Why would a wider zoom replace two lenses on the trail?"], "shortAnswer": "In a two-trip climbing test, the Sony 20-70mm f/4 G beat the 24-50mm f/2.8 G as a replacement for a 24-70mm f/2.8. The 20mm wide end saved a separate wide lens swap, acting like two lenses in one, while the 24-50mm's size advantage felt smaller on the trail than the spec sheet suggests and it costs several hundred dollars more than the Sigma it was meant to replace.", "url": "/blog/sony-20-70mm-mountain-zoom.html", "access": "free", "topics": ["lenses", "sony", "landscape", "travel"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/sony-20-70mm-mountain-zoom.jpg"}, {"id": "blog-sony-a7rvi-firmware-102-preset-focus", "type": "article", "title": "Sony Gave Your Telephoto Lens a Memory", "questions": ["What changed in Sony A7R VI firmware 1.02?", "What is Preset Focus on the Sony A7R VI?", "How does preset focus help with wildlife photography?"], "shortAnswer": "Firmware 1.02 for the Sony A7R VI extends Preset Focus to non-power-zoom lenses, so you can save a focus distance to a custom button and snap back to it with one press instead of needing a tethered computer. For wildlife, pre-focus on the spot the animal keeps returning to and one press puts focus exactly there when it comes back. Some lenses are still excluded, so check Sony's compatibility chart.", "url": "/blog/sony-a7rvi-firmware-102-preset-focus.html", "access": "free", "topics": ["sony", "firmware", "autofocus", "wildlife"], "level": "intermediate", "brand": "Sony", "model": "A7R VI", "leadsTo": "Camera Select", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/sony-a7rvi-firmware-102-preset-focus.jpg"}, {"id": "blog-space-jellyfish-spacex-plume", "type": "article", "title": "A Rocket Left a Glowing 'Space Jellyfish' Over Florida. Here Is How to Catch the Next One", "questions": ["What is the glowing space jellyfish after a rocket launch?", "How do you photograph a rocket launch plume at dawn?", "Do I need to be close to the launch pad to see a space jellyfish?"], "shortAnswer": "A space jellyfish is a rocket's expanding exhaust plume in the thin upper atmosphere catching sunlight while the ground below is still dark, which happens in the minutes before sunrise or near sunset. You do not need to be at the pad; the plume can be visible hundreds of miles away. Scout a foreground the day before, arrive with a tripod while it is still dark, frame wide, and expose for the glowing cloud rather than the black sky.", "url": "/blog/space-jellyfish-spacex-plume.html", "access": "free", "topics": ["night sky", "rocket launch", "planning", "long exposure"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/space-jellyfish-spacex-plume.jpg"}, {"id": "blog-tamron-16-50mm-f28-aps-c", "type": "article", "title": "The $549 f/2.8 Zoom That Makes APS-C Feel Like a Pro System", "questions": ["What is a good first upgrade lens for an APS-C camera?", "Why is a constant f/2.8 zoom better for learning than a kit lens?", "What does Tamron's 16-50mm f/2.8 cost and fit?"], "shortAnswer": "Tamron's 16-50mm f/2.8 fits Sony, Canon, Fujifilm, and Nikon crop-sensor cameras, at $529 for Sony E and Fujifilm X and $549 for Canon RF and Nikon Z; it weighs 305 grams, 315 in the Nikon Z version. A kit lens changes aperture as you zoom, so your exposure shifts without you touching anything; a constant f/2.8 keeps the aperture you set at every focal length, so the exposure triangle behaves the way the books say it does.", "url": "/blog/tamron-16-50mm-f28-aps-c.html", "access": "free", "topics": ["lenses", "aps-c", "exposure", "gear"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Protocol 014: What to Buy First (When You Have $500)", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/tamron-16-50mm-f28-aps-c.jpg"}, {"id": "blog-tamron-20-40mm-f28-nikon-z", "type": "article", "title": "Tamron's 20-40mm f/2.8 Comes to Nikon Z", "questions": ["What is Tamron's 20-40mm f/2.8 for Nikon Z?", "What would I shoot with a 20-40mm zoom?", "How much does the Tamron 20-40mm f/2.8 cost for Nikon Z?"], "shortAnswer": "Tamron's 20-40mm f/2.8 arrives for Nikon Z on October 22 for $729, running from genuine ultrawide for architecture, interiors, and big landscapes to 40mm for environmental portraits and walk-around shooting. It is the same optical design as the 2022 Sony E version, weighs 380 grams, and its limited range forces you to move your feet instead of just twisting the ring.", "url": "/blog/tamron-20-40mm-f28-nikon-z.html", "access": "free", "topics": ["lenses", "nikon z", "wide angle", "tamron"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/tamron-20-40mm-f28-nikon-z.jpg"}, {"id": "blog-telephoto-sea-of-fog-layers", "type": "article", "title": "A Telephoto Turns a Sea of Fog Into a Dozen Photographs", "questions": ["How do you photograph fog so it does not look like one grey blanket?", "What lens and settings work for fog layers?", "Why use a telephoto lens for fog instead of a wide angle?"], "shortAnswer": "Point a long lens, like a 100-400mm zoom, at fog and one washed-out view becomes many small pictures: a ridge, treetops, or mist spilling over a hill, each isolated on its own, with distant ridges stacking into layers. The working rule from the article is a shutter speed of about double the focal length, around 1/800 at 400mm, with aperture mattering little at f/8 when everything is at infinity.", "url": "/blog/telephoto-sea-of-fog-layers.html", "access": "free", "topics": ["fog", "telephoto", "landscape", "composition"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/telephoto-sea-of-fog-layers.jpg"}, {"id": "blog-ten-years-one-subject", "type": "article", "title": "What Ten Years With One Subject Can Teach You", "questions": ["Why should I keep photographing the same subject for years?", "What does a long term photo project give you that new subjects do not?", "How do I start a long term photography project?"], "shortAnswer": "Staying with one subject beats chasing novelty: the early frames show what a place looks like, and the later ones show what it means to the people in it, because returning builds relationships and access. You do not need a decade to use it; pick one subject you can return to, like a market, a team, or a street, and go back four times instead of going somewhere new four times.", "url": "/blog/ten-years-one-subject.html", "access": "free", "topics": ["projects", "documentary", "persistence", "storytelling"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/ten-years-one-subject.jpg"}, {"id": "blog-upgrade-camera-or-not", "type": "article", "title": "Is It Time to Upgrade Your Camera? A Marsh Test Answers It", "questions": ["Is it time to upgrade my camera?", "Does shooting with an old camera make you a better photographer?", "What camera upgrade actually improves your hit rate?"], "shortAnswer": "An older camera can still produce a beautiful file, but a field test of a 2018 Fujifilm X-H1 on fast wildlife showed the real cost: you place and hold the focus point on a moving subject yourself. The upgrade that changes your hit rate is subject-detection autofocus that recognizes birds, animals, and vehicles, not more megapixels. If your shooting involves anything fast, that detection is the line between a camera that helps you and one you fight.", "url": "/blog/upgrade-camera-or-not.html", "access": "free", "topics": ["gear", "upgrading", "autofocus", "wildlife"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Protocol 017: When the Upgrade Is Actually Worth It", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/upgrade-camera-marsh.jpg"}, {"id": "blog-why-ultra-wide-landscapes-look-flat", "type": "article", "title": "Your Ultra-Wide Landscapes Look Flat Because You Are Standing Too Far Back", "questions": ["Why do my ultra-wide landscape photos look flat?", "How close should I get to the foreground in a wide landscape?", "How do I get depth back in an ultra-wide photo?"], "shortAnswer": "An ultra-wide lens does not flatten a landscape by itself; standing too far from the foreground does, because distant objects shrink far more than your eye expects. Get within a foot or two of the nearest object so near things loom and everything else recedes in steps. That closeness pushes depth of field to its limit, which is why many landscape shooters pair near foregrounds with focus stacking.", "url": "/blog/why-ultra-wide-landscapes-look-flat.html", "access": "free", "topics": ["landscape", "wide angle", "composition", "depth"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/why-ultra-wide-landscapes-look-flat.jpg"}, {"id": "blog-wide-medium-close-landscape-trick", "type": "article", "title": "Shoot Every Landscape Three Times: Wide, Medium, Close", "questions": ["How do I get more than one good photo from a single landscape location?", "What is the wide medium close shooting sequence?", "How do filmmakers cover a scene and can I use it for photos?"], "shortAnswer": "Borrow how filmmakers cover a scene: shoot every landscape three times, one wide, one medium, and one close. Set the rule before you leave the car, one frame at the wide end of your zoom, one near 50mm, and one at the long end, and do not pack up until you have all three. If the sky goes flat, a close-up of texture barely notices, so the sequence spreads your risk on uncertain mornings.", "url": "/blog/wide-medium-close-landscape-trick.html", "access": "free", "topics": ["landscape", "composition", "shooting exercise", "sequence"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Shoot Lab", "status": "tagged", "source": "Cameras Decoded, the item's own page", "img": "/blog-images/wide-medium-close-trick.jpg"}, {"id": "blog-wide-open-aperture-depth-light-layers", "type": "article", "title": "Blur Is the Shortcut. Depth Is the Skill.", "questions": ["How do I get depth in a photo without shooting wide open?", "Is background blur the only way to show depth?", "What makes a photo look three dimensional?"], "shortAnswer": "Depth is built in the scene with light and layers, not with the aperture dial. Directional light from about 45 degrees above and to the side makes bands of light and shadow alternate through the frame, and a clear foreground, midground, and background do the rest. Shooting wide open is the shortcut version of depth, and phones have faked that blur in software since 2016, so it no longer proves a picture was made with care.", "url": "/blog/wide-open-aperture-depth-light-layers.html", "access": "free", "topics": ["depth", "aperture", "light", "composition"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/wide-open-aperture-depth-light-layers.jpg"}, {"id": "blog-worthwait-app-wont-let-you-chimp", "type": "article", "title": "The App That Won't Let You Chimp", "questions": ["What is the WorthWait app?", "Why would a camera app hide my photos for 24 hours?", "What is chimping and why is it a bad habit?"], "shortAnswer": "WorthWait is an iPhone camera app that recreates the disposable camera experience: you load a roll on a fixed 35mm-equivalent lens and wait 24 hours before the photos develop, with no peeking. The free version covers one 24-exposure roll at a time, four film looks, and a Blind Mode with no viewfinder at all; 36-exposure rolls come with Plena, the paid one-time upgrade. The wait matters because checking the screen after every shot, called chimping, breaks your attention and has you judging frames with anxiety instead of reading the scene.", "url": "/blog/worthwait-app-wont-let-you-chimp.html", "access": "free", "topics": ["phone photography", "apps", "habits", "film look"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/worthwait-app-wont-let-you-chimp.jpg"}, {"id": "blog-young-wildlife-photographer-2026-dung-beetle", "type": "article", "title": "A 14-Year-Old Won Wildlife Photographer of the Year With a Dung Beetle", "questions": ["Who won Young Wildlife Photographer of the Year 2026?", "How did a 14 year old photograph a dung beetle to win?", "What camera technique won the young wildlife title?"], "shortAnswer": "Oscar Whitfield, 14, won Young Wildlife Photographer of the Year 2026 with Labour of Love, a black-and-white photo of a dung beetle pushing a ball of dung uphill in Zambezi National Park. His technique was humble: instead of standing over the beetle he lay flat, put the camera at the insect's eye level, and shot fast. For the first time in the competition's 62-year history, black-and-white photographs took both the young and adult top titles.", "url": "/blog/young-wildlife-photographer-2026-dung-beetle.html", "access": "free", "topics": ["wildlife", "competitions", "eye level", "black and white"], "level": "beginner", "brand": "", "model": "", "leadsTo": "The Arena", "status": "checked", "source": "Outside sources, checked 2026-11-01 during the Ask CD verification pass", "img": "/blog-images/young-wildlife-photographer-2026-dung-beetle.jpg"}, {"id": "fm1", "type": "manual", "title": "Field Manual No. 01: Camera Craft", "questions": ["What's in Field Manual No. 01?", "Where do I learn the basics of using my camera properly?", "Which Field Manual teaches camera craft from the start?"], "shortAnswer": "Field Manual No. 01 is the camera-craft manual: 5 chapters and 16 lessons. Chapters 1 to 3 are free, chapters 4 and 5 are Pro.", "url": "/field-manual.html", "access": "mixed", "topics": ["fundamentals", "exposure", "camera craft"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Camera Confidence Guide (the book, $47)", "status": "tagged", "source": "Field Manuals shelf", "img": ""}, {"id": "fm1-ch01", "type": "manual-chapter", "title": "Field Manual No. 01, Chapter 01: Introduction", "questions": ["I'm brand new, where does Field Manual No. 01 start?", "What is the first chapter of the camera craft manual?"], "shortAnswer": "Chapter 01 is the Introduction to Field Manual No. 01, the free starting point of the camera-craft manual.", "url": "/field-manual.html", "access": "free", "topics": ["introduction", "getting started"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01, Chapter 02: Getting Started", "status": "tagged", "source": "guideContent/curriculum (Firestore)", "img": ""}, {"id": "fm1-ch02", "type": "manual-chapter", "title": "Field Manual No. 01, Chapter 02: Getting Started", "questions": ["What's after the introduction in Field Manual No. 01?", "Which chapter helps me get started with my camera in the manual?"], "shortAnswer": "Chapter 02 of Field Manual No. 01 is Getting Started, the second of the manual's free opening chapters (chapters 1 to 3 are free).", "url": "/field-manual.html", "access": "free", "topics": ["getting started", "basics"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01, Chapter 03: The Fundamentals", "status": "tagged", "source": "guideContent/curriculum (Firestore)", "img": ""}, {"id": "fm1-ch03", "type": "manual-chapter", "title": "Field Manual No. 01, Chapter 03: The Fundamentals", "questions": ["Where do I learn the fundamentals of photography in the app?", "What does the Fundamentals chapter of Field Manual No. 01 cover?"], "shortAnswer": "Chapter 03 of Field Manual No. 01 is The Fundamentals, the third free chapter of the camera-craft manual.", "url": "/field-manual.html", "access": "free", "topics": ["fundamentals", "basics"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01, Chapter 04: The Creative Craft (Pro)", "status": "tagged", "source": "guideContent/curriculum (Firestore)", "img": ""}, {"id": "fm1-ch04", "type": "manual-chapter", "title": "Field Manual No. 01, Chapter 04: The Creative Craft", "questions": ["What's in the Creative Craft chapter of Field Manual No. 01?", "Which Field Manual chapter goes past the fundamentals into creative work?"], "shortAnswer": "Chapter 04 of Field Manual No. 01 is The Creative Craft; it is a Pro chapter, past the three free opening chapters.", "url": "/field-manual.html", "access": "pro", "topics": ["creative craft", "pro"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 01, Chapter 05 (Pro)", "status": "tagged", "source": "guideContent/curriculum (Firestore)", "img": ""}, {"id": "fm1-ch05", "type": "manual-chapter", "title": "Field Manual No. 01, Chapter 05 (title taken from live curriculum in the tagging pass)", "questions": ["What's the last chapter of Field Manual No. 01?", "What does chapter 5 of the camera craft manual cover?"], "shortAnswer": "Chapter 05 is the final chapter of Field Manual No. 01 and it is Pro. The index does not yet carry this chapter's own title or lesson detail, so this entry can only place it as the manual's closing Pro chapter for now.", "url": "/field-manual.html", "access": "pro", "topics": ["camera craft", "pro"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Camera Confidence Guide (the book, $47)", "status": "tagged", "source": "guideContent/curriculum (Firestore)", "img": ""}, {"id": "fm2-ch01", "type": "manual-chapter", "title": "Field Manual No. 02 The Finish, Chapter 1: Read Before You Touch", "questions": ["What should I do before I start editing a photo?", "Where does the editing manual on Cameras Decoded start?"], "shortAnswer": "Read Before You Touch is chapter 1 of Field Manual No. 02, The Finish, the editing manual; it is the free opening chapter, about what to sort out before you touch a photo.", "url": "/field-manual.html", "access": "free", "topics": ["editing", "workflow"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 02, Chapter 2: The Global Grade", "status": "tagged", "source": "guideContent/finish (Firestore)", "img": ""}, {"id": "fm2-ch02", "type": "manual-chapter", "title": "Field Manual No. 02 The Finish, Chapter 2: The Global Grade", "questions": ["What is a global grade in editing?", "Which chapter of The Finish covers grading the whole photo first?"], "shortAnswer": "The Global Grade is chapter 2 of Field Manual No. 02, The Finish, covering the whole-photo grade; it is a Pro chapter.", "url": "/field-manual.html", "access": "pro", "topics": ["editing", "grading"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 02, Chapter 3: Color Is a Decision", "status": "tagged", "source": "guideContent/finish (Firestore)", "img": ""}, {"id": "fm2-ch03", "type": "manual-chapter", "title": "Field Manual No. 02 The Finish, Chapter 3: Color Is a Decision", "questions": ["How do I make better color choices when I edit?", "Which chapter of The Finish is about color?"], "shortAnswer": "Color Is a Decision is chapter 3 of Field Manual No. 02, The Finish, the editing manual's chapter on color; it is a Pro chapter.", "url": "/field-manual.html", "access": "pro", "topics": ["editing", "color"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Field Manual No. 02, Chapter 4: Looks & Taste", "status": "tagged", "source": "guideContent/finish (Firestore)", "img": ""}, {"id": "fm2-ch04", "type": "manual-chapter", "title": "Field Manual No. 02 The Finish, Chapter 4: Looks & Taste", "questions": ["How do I develop my own editing style or look?", "Which chapter of The Finish covers looks and taste?"], "shortAnswer": "Looks & Taste is chapter 4 of Field Manual No. 02, The Finish, the chapter on looks and personal taste in editing; it is a Pro chapter.", "url": "/field-manual.html", "access": "pro", "topics": ["editing", "style", "looks"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Develop Lab", "status": "tagged", "source": "guideContent/finish (Firestore)", "img": ""}, {"id": "fm2-ch05", "type": "manual-chapter", "title": "Field Manual No. 02 The Finish, Chapter 5: Finish & Ship", "questions": ["How do I finish and deliver an edited photo properly?", "What's the last chapter of the editing manual?"], "shortAnswer": "Finish & Ship is chapter 5 of Field Manual No. 02, The Finish, the closing chapter on finishing and shipping edited work; it is a Pro chapter.", "url": "/field-manual.html", "access": "pro", "topics": ["editing", "finishing", "delivery"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Deliver (client galleries)", "status": "tagged", "source": "guideContent/finish (Firestore)", "img": ""}, {"id": "prod-guide", "type": "product", "title": "Camera Confidence Guide (the book, $47)", "questions": ["What's the Camera Confidence Guide and how much is it?", "Is there a book that teaches me to use my mirrorless camera?", "What's the difference between the Guide and the Field Manuals?"], "shortAnswer": "The Camera Confidence Guide is a 142-page illustrated mirrorless curriculum narrated by Cynetis-7, and it is the book itself, its own product. It costs $47 while the Founding window is open, $97 after, and annual Pro includes it free.", "url": "/camera-confidence-guide.html", "access": "paid", "topics": ["learning", "mirrorless", "book"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01: Camera Craft", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": "/camera-confidence-guide-cover.jpg"}, {"id": "prod-pro", "type": "product", "title": "Cameras Decoded Pro", "questions": ["What do I get with Cameras Decoded Pro?", "How much does Pro cost?", "What does Pro unlock in the app?"], "shortAnswer": "Pro unlocks the deep Field Manual chapters, the Camera Select Pro lessons, and the protocols from 022 on. It costs $4.99 a week, $14.99 a month, or $119 a year, and the annual plan is the hero plan.", "url": "/pro-checkout.html", "access": "paid", "topics": ["pro", "subscription", "unlocks"], "level": "beginner", "brand": "", "model": "", "leadsTo": "", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "prod-presets", "type": "product", "title": "Pro Presets (as listed in the store)", "questions": ["What are the Pro Presets in the store?", "Does Cameras Decoded sell editing presets?"], "shortAnswer": "Pro Presets is a paid item listed in the Cameras Decoded store, in the editing and presets category. The index only has its store listing, so there is no detail yet on what is inside it.", "url": "/products.html", "access": "paid", "topics": ["editing", "presets", "store"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Develop Lab", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "free-hero-card", "type": "product", "title": "Exposure Triangle Cheat Card (free, no sign-in)", "questions": ["Is there a free exposure cheat sheet I can keep on my phone?", "What free download can I get without signing up?", "I keep forgetting how aperture, shutter speed, and ISO work together, is there a one-page card?"], "shortAnswer": "The Exposure Triangle Cheat Card is a free download on the Free page with no sign-in needed, made to be kept and shared: one card covering how exposure works.", "url": "/free.html", "access": "free", "topics": ["exposure", "cheat card", "free"], "level": "beginner", "brand": "", "model": "", "leadsTo": "The cheat-sheet pack on the Free page", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "tool-develop-lab", "type": "tool", "title": "Develop Lab", "questions": ["Where do I edit my photos in the app?", "Does Cameras Decoded have a photo editor?", "Where can I develop my RAW photos?"], "shortAnswer": "Develop Lab is Cameras Decoded's own photo editing tool, for editing and developing your photos, including RAW work.", "url": "/darkroom-lab.html", "access": "mixed", "topics": ["editing", "raw", "tool"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 02: The Finish", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "tool-clip-lab", "type": "tool", "title": "Clip Lab", "questions": ["Where do I finish a video clip in the app?", "Can I add captions to a clip on my phone here?", "What tool do I use for short video clips?"], "shortAnswer": "Clip Lab is Cameras Decoded's tool for video clips, including captions, and it works on your phone.", "url": "/clip-lab.html", "access": "mixed", "topics": ["video", "captions", "tool"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 02: The Finish", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "tool-shoot-lab", "type": "tool", "title": "Shoot Lab", "questions": ["Where can I practice shooting in the app?", "What is Shoot Lab for?"], "shortAnswer": "Shoot Lab is Cameras Decoded's tool for shooting practice.", "url": "/shoot-lab.html", "access": "mixed", "topics": ["shooting", "practice", "tool"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01: Camera Craft", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "tool-exposure-lab", "type": "tool", "title": "Exposure Lab", "questions": ["Where can I practice exposure settings without wasting real shots?", "What is Exposure Lab for?"], "shortAnswer": "Exposure Lab is Cameras Decoded's practice tool for exposure, where you can work on settings before they cost you a real shot.", "url": "/exposure-lab.html", "access": "mixed", "topics": ["exposure", "practice", "tool"], "level": "beginner", "brand": "", "model": "", "leadsTo": "Field Manual No. 01: Camera Craft", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "tool-ai-workbench", "type": "tool", "title": "AI Workbench", "questions": ["What AI tools does Cameras Decoded have for my workflow?", "What is the AI Workbench for?"], "shortAnswer": "The AI Workbench is Cameras Decoded's tool for AI help with your photography workflow.", "url": "/ai-workbench.html", "access": "mixed", "topics": ["ai", "workflow", "tool"], "level": "intermediate", "brand": "", "model": "", "leadsTo": "Protocol 015: Using AI for Culling", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "tool-deliver", "type": "tool", "title": "Deliver", "questions": ["How do I deliver photos to clients in the app?", "Where do client galleries live on Cameras Decoded?", "What tool sends finished work to clients?"], "shortAnswer": "Deliver is Cameras Decoded's tool for client work: galleries and getting finished photos to the people who hired you.", "url": "/deliver.html", "access": "mixed", "topics": ["clients", "galleries", "business", "tool"], "level": "pro", "brand": "", "model": "", "leadsTo": "Protocol 016: The Post-Shoot Email That Books the Next Gig", "status": "tagged", "source": "The item's own page on camerasdecoded.com", "img": ""}, {"id": "signal-feed", "type": "signal-source", "title": "The Signal (community feed)", "questions": [], "shortAnswer": "Signal posts are live community posts in Firestore (feedItems). They are matched by topic at answer time and shown as examples and discussion, never as the verified source an answer rests on.", "url": "/feed.html", "access": "account", "topics": [], "level": "", "brand": "", "model": "", "leadsTo": "", "status": "design-note", "source": "Firestore feedItems (live)", "img": ""}];
